INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz---rock-angelz-utrashman', 'GAMEBOYADVANCE', 'Bratz - Rock Angelz (U)(Trashman)', '2005', 'Adventure', 'Altron', '1', 'Adventure', 'Adventure and rhythm-based action.', 'Start your own fashion magazine and rock the world.', 'Go on a world tour and build a fashion empire with the Bratz.', 'Bratz - Rock Angelz for GBA combines social adventure with creative design. Work at the Bratz office, fly to international locations, and master the world of music and fashion in this comprehensive handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz---the-movie-epuppa', 'GAMEBOYADVANCE', 'Bratz - The Movie (E)(Puppa)', '2007', 'Adventure', 'Altron', '1', 'Adventure', 'Adventure and mini-game collection based on the film.', 'Navigate the highs and lows of making a Hollywood movie.', 'Experience the excitement of movie-making with the Bratz.', 'Bratz - The Movie lets you step onto the film set. Help the girls with their roles, participate in rehearsals, and manage their red-carpet looks in this engaging adventure based on the theatrical release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz---the-movie-esir-vg', 'GAMEBOYADVANCE', 'Bratz - The Movie (E)(Sir VG)', '2007', 'Adventure', 'Altron', '1', 'Adventure', 'Adventure and mini-game collection based on the film.', 'Navigate the highs and lows of making a Hollywood movie.', 'Experience the excitement of movie-making with the Bratz.', 'Bratz - The Movie features various gameplay styles, including rhythm challenges and fashion puzzles. Guide the girls through their Hollywood debut and ensure the movie is a total hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz---the-movie-gindependent', 'GAMEBOYADVANCE', 'Bratz - The Movie (G)(Independent)', '2007', 'Adventure', 'Altron', '1', 'Adventure', 'Adventure and mini-game collection based on the film.', 'Navigate the highs and lows of making a Hollywood movie.', 'German-localized movie-making adventure with the Bratz.', 'Bratz - The Movie (German Version) provides the full cinematic experience on GBA. Explore diverse locations, interact with characters from the film, and master the art of fashion and fame.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz---the-movie-usir-vg', 'GAMEBOYADVANCE', 'Bratz - The Movie (U)(Sir VG)', '2007', 'Adventure', 'Altron', '1', 'Adventure', 'Adventure and mini-game collection based on the film.', 'Navigate the highs and lows of making a Hollywood movie.', 'Experience the excitement of movie-making with the Bratz.', 'The US version of Bratz - The Movie delivers high-energy gameplay for fans. Customize your favorite characters, solve studio-related puzzles, and help the Bratz girls become true Hollywood icons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz-erising-sun', 'GAMEBOYADVANCE', 'Bratz (E)(Rising Sun)', '2002', 'Adventure', 'Altron', '1', 'Adventure', 'Adventure and fashion-themed mini-games.', 'Complete various social tasks and style challenges.', 'The original Bratz adventure for the Game Boy Advance.', 'Bratz for GBA introduces players to the world of Cloé, Jade, Sasha, and Yasmin. Engage in a series of fun mini-games that focus on fashion, music, and the power of friendship in this colorful handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz-ueurasia', 'GAMEBOYADVANCE', 'Bratz (U)(Eurasia)', '2002', 'Adventure', 'Altron', '1', 'Adventure', 'Adventure and fashion-themed mini-games.', 'Complete various social tasks and style challenges.', 'The original Bratz adventure for the Game Boy Advance.', 'The US version of Bratz features accessible gameplay perfect for younger fans. Navigate the neighborhood, help your friends with their fashion emergencies, and collect items to unlock new stylish outfits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz-babyz-eindependent', 'GAMEBOYADVANCE', 'Bratz Babyz (E)(Independent)', '2006', 'Simulation', 'Altron', '1', 'Life Simulation', 'Multi-genre adventure with baby characters.', 'Help the Bratz Babyz find their lost pets and save the day.', 'A cute and wacky adventure featuring the younger Bratz.', 'Bratz Babyz for GBA offers a series of fun challenges starring the baby versions of the iconic dolls. Use their unique toddler skills to navigate puzzles and rescue their beloved pets in this charming adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz-babyz-usir-vg', 'GAMEBOYADVANCE', 'Bratz Babyz (U)(Sir VG)', '2006', 'Simulation', 'Altron', '1', 'Life Simulation', 'Multi-genre adventure with baby characters.', 'Help the Bratz Babyz find their lost pets and save the day.', 'A cute and wacky adventure featuring the younger Bratz.', 'The US version of Bratz Babyz features vibrant graphics and simple controls. Explore the local mall and neighborhood from a baby''s perspective while completing fun missions and mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz-rock-angelz-grising-sun', 'GAMEBOYADVANCE', 'Bratz Rock Angelz (G)(Rising Sun)', '2005', 'Adventure', 'Altron', '1', 'Adventure', 'Adventure and rhythm-based action.', 'Start your own fashion magazine and rock the world.', 'German-localized edition of the Rock Angelz adventure.', 'Bratz Rock Angelz (German Version) follows the girls as they launch their fashion magazine and travel the world. Master the rhythm segments and design the perfect cover story for the Rock Angelz brand.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-eindependent', 'GAMEBOYADVANCE', 'Breath of Fire (E)(Independent)', '2001', 'RPG', 'Capcom', '1', 'JRPG', 'Classic turn-based RPG with exploration.', 'Lead the Light Dragon Clan to defeat the Dark Dragon empire.', 'The legendary Capcom RPG reimagined for the GBA.', 'Breath of Fire is a definitive 16-bit RPG experience. Join Ryu and a cast of unique companions on an epic quest to stop a global war, featuring deep combat, character transformations, and a vast world to explore.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-erocket', 'GAMEBOYADVANCE', 'Breath of Fire (E)(Rocket)', '2001', 'RPG', 'Capcom', '1', 'JRPG', 'Classic turn-based RPG with exploration.', 'Lead the Light Dragon Clan to defeat the Dark Dragon empire.', 'The legendary Capcom RPG reimagined for the GBA.', 'Breath of Fire for GBA features refined graphics and a convenient save system. Master Ryu''s dragon transformations and utilize each party member''s special field abilities to uncover secrets and save the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-jeurasia', 'GAMEBOYADVANCE', 'Breath of Fire (J)(Eurasia)', '2001', 'RPG', 'Capcom', '1', 'JRPG', 'Classic turn-based RPG with exploration.', 'Lead the Light Dragon Clan to defeat the Dark Dragon empire.', 'The original Japanese release of the acclaimed RPG series.', 'Breath of Fire (Japanese Version) offers the authentic start to Ryu''s journey. Experience the deep story and tactical turn-based battles that made this series a cornerstone of the RPG genre on handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-umode7', 'GAMEBOYADVANCE', 'Breath of Fire (U)(Mode7)', '2001', 'RPG', 'Capcom', '1', 'JRPG', 'Classic turn-based RPG with exploration.', 'Lead the Light Dragon Clan to defeat the Dark Dragon empire.', 'The legendary Capcom RPG reimagined for the GBA.', 'The US version of Breath of Fire delivers an epic fantasy narrative. Explore massive dungeons, engage in strategic combat, and witness the power of the Dragon Clan in this high-quality portable role-playing game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-2---shimei-no-ko-jeurasia', 'GAMEBOYADVANCE', 'Breath of Fire 2 - Shimei no Ko (J)(Eurasia)', '2001', 'RPG', 'Capcom', '1', 'JRPG', 'Turn-based RPG with party management.', 'Discover the truth behind your past and stop a rising evil.', 'The epic sequel to the Dragon Clan saga in its original Japanese form.', 'Breath of Fire 2 - Shimei no Ko brings a deep, mature narrative to the GBA. Recruit diverse allies, manage your own town, and master powerful dragon transformations in this classic 16-bit RPG carefully adapted for handheld play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-2-epatience', 'GAMEBOYADVANCE', 'Breath of Fire 2 (E)(Patience)', '2001', 'RPG', 'Capcom', '1', 'JRPG', 'Turn-based RPG with party management.', 'Discover the truth behind your past and stop a rising evil.', 'Journey with Ryu and Bow in this legendary fantasy RPG adventure.', 'Breath of Fire 2 for GBA features refined visuals and a revamped translation. Experience one of the most emotional stories in the genre, featuring a unique "TownShip" building mechanic and strategic turn-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-2-umode7', 'GAMEBOYADVANCE', 'Breath of Fire 2 (U)(Mode7)', '2001', 'RPG', 'Capcom', '1', 'JRPG', 'Turn-based RPG with party management.', 'Discover the truth behind your past and stop a rising evil.', 'Journey with Ryu and Bow in this legendary fantasy RPG adventure.', 'The US version of Breath of Fire 2 delivers a massive quest on your handheld. Lead a team of half-human heroes, explore a vast world, and uncover a religious conspiracy in this definitive portable role-playing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('britneys-dance-beat-epatience', 'GAMEBOYADVANCE', 'Britney''s Dance Beat (E)(Patience)', '2002', 'Music', 'Artificial Mind & Movement', '1', 'Rhythm', 'Rhythm-based button timing and music action.', 'Audition and earn your place as a backup dancer for Britney Spears.', 'Test your rhythm and coordination in this pop-star dance challenge.', 'Britney''s Dance Beat for GBA lets you groove to hit songs like "Oops!... I Did It Again." Master the timing-based gameplay to impress the scouts and climb the ranks of the professional dance world in this high-energy music game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('britneys-dance-beat-esir-vg', 'GAMEBOYADVANCE', 'Britney''s Dance Beat (E)(Sir VG)', '2002', 'Music', 'Artificial Mind & Movement', '1', 'Rhythm', 'Rhythm-based button timing and music action.', 'Audition and earn your place as a backup dancer for Britney Spears.', 'Test your rhythm and coordination in this pop-star dance challenge.', 'This European release features the signature pop aesthetic of the early 2000s. Guide your dancer through various auditions, unlock exclusive photos, and prove you have the moves to perform alongside the Princess of Pop.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('britneys-dance-beat-umode7', 'GAMEBOYADVANCE', 'Britney''s Dance Beat (U)(Mode7)', '2002', 'Music', 'Artificial Mind & Movement', '1', 'Rhythm', 'Rhythm-based button timing and music action.', 'Audition and earn your place as a backup dancer for Britney Spears.', 'Test your rhythm and coordination in this pop-star dance challenge.', 'The US version of Britney''s Dance Beat offers addictive rhythm gameplay on the go. Perfect your timing across multiple difficulty levels and enjoy a handheld tribute to one of music''s biggest icons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('broken-sword---the-shadow-of-the-templars-evenom', 'GAMEBOYADVANCE', 'Broken Sword - The Shadow of the Templars (E)(Venom)', '2003', 'Adventure', 'Revolution Software', '1', 'Point and Click', 'Point-and-click adventure with puzzle-solving.', 'Solve a mysterious murder in Paris and uncover a Templar plot.', 'A cinematic mystery adventure featuring George Stobbart.', 'Broken Sword - The Shadow of the Templars is a masterpiece of storytelling. Navigate hand-drawn environments, solve complex logic puzzles, and engage in witty dialogue in this high-quality GBA port of the legendary PC adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('broken-sword---the-shadow-of-the-templars-unobody', 'GAMEBOYADVANCE', 'Broken Sword - The Shadow of the Templars (U)(Nobody)', '2003', 'Adventure', 'Revolution Software', '1', 'Point and Click', 'Point-and-click adventure with puzzle-solving.', 'Solve a mysterious murder in Paris and uncover a Templar plot.', 'A cinematic mystery adventure featuring George Stobbart.', 'The US version of Broken Sword brings a mature, globe-trotting thriller to your pocket. Help George and Nico uncover ancient secrets in a plot filled with suspense, history, and dry humor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bruce-lee---return-of-the-legend-evenom', 'GAMEBOYADVANCE', 'Bruce Lee - Return of the Legend (E)(Venom)', '2003', 'Action', 'Vicarious Visions', '1', 'Action Platformer', 'Side-scrolling beat ''em up and stealth action.', 'Stop the criminal organization and avenge your master.', 'Play as the martial arts legend in this stylish action brawler.', 'Bruce Lee - Return of the Legend captures the essence of Jeet Kune Do. Fight through guards using iconic moves, master stealth-based infiltration, and relive the cinematic feel of a classic 70s kung-fu movie on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bruce-lee---return-of-the-legend-uindependent', 'GAMEBOYADVANCE', 'Bruce Lee - Return of the Legend (U)(Independent)', '2003', 'Action', 'Vicarious Visions', '1', 'Action Platformer', 'Side-scrolling beat ''em up and stealth action.', 'Stop the criminal organization and avenge your master.', 'Play as the martial arts legend in this stylish action brawler.', 'The US version of Return of the Legend features fluid combat animations and challenging boss fights. Use Bruce Lee''s speed and strength to navigate dangerous levels in this top-tier handheld martial arts adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubble-bobble---old-&-new-evenom', 'GAMEBOYADVANCE', 'Bubble Bobble - Old & New (E)(Venom)', '2002', 'Platform', 'Taito', '2', 'Arcade Platformer', 'Arcade platformer with bubble-shooting mechanics.', 'Clear all enemies by trapping them in bubbles and popping them.', 'Experience the arcade classic and its modern remake in one.', 'Bubble Bobble - Old & New brings Bub and Bob to the GBA. Play the pixel-perfect original arcade hit or switch to the "New" mode featuring updated graphics, sound, and refined gameplay mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubble-bobble---old-&-new-jeurasia', 'GAMEBOYADVANCE', 'Bubble Bobble - Old & New (J)(Eurasia)', '2002', 'Platform', 'Taito', '2', 'Arcade Platformer', 'Arcade platformer with bubble-shooting mechanics.', 'Clear all enemies by trapping them in bubbles and popping them.', 'Experience the arcade classic and its modern remake in one.', 'The Japanese version of Bubble Bobble - Old & New offers the same addictive coop-style action. Master the art of bubble jumping to reach hidden items and clear 100 levels of classic arcade fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubble-bobble---old-&-new-uchameleon', 'GAMEBOYADVANCE', 'Bubble Bobble - Old & New (U)(Chameleon)', '2002', 'Platform', 'Taito', '2', 'Arcade Platformer', 'Arcade platformer with bubble-shooting mechanics.', 'Clear all enemies by trapping them in bubbles and popping them.', 'Experience the arcade classic and its modern remake in one.', 'Bubble Bobble - Old & New (US) is the definitive way to play this puzzle-platformer. Featuring a great balance of retro charm and modern polish, it’s a must-have for fans of high-score chasing and colorful action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('buffy-contre-les-vampires---la-colere-de-darkhul-frising-sun', 'GAMEBOYADVANCE', 'Buffy Contre Les Vampires - La Colere De Darkhul (F)(Rising Sun)', '2003', 'Action', 'Natsume', '1', 'Action Adventure', 'Side-scrolling action brawler with platforming.', 'Stop the vampire threat and prevent the resurrection of Darkhul.', 'Protect Sunnydale as the Chosen One in this French action hit.', 'Buffy Contre Les Vampires offers intense combat against the undead. Use Buffy''s martial arts and iconic weapons like "Mr. Pointy" to clear the streets and cemeteries of vampires in this atmospheric GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('buffy-im-bann-der-damonen-gsuxxors', 'GAMEBOYADVANCE', 'Buffy Im Bann Der Damonen (G)(Suxxors)', '2003', 'Action', 'Natsume', '1', 'Action Adventure', 'Side-scrolling action brawler with platforming.', 'Stop the vampire threat and prevent the resurrection of Darkhul.', 'Protect Sunnydale as the Chosen One in this German action hit.', 'Buffy Im Bann Der Damonen brings the TV show''s drama to handheld. Battle through various locations from the series, utilize special combat moves, and face off against the powerful vampire Darkhul.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('buffy-the-vampire-slayer-umode7', 'GAMEBOYADVANCE', 'Buffy The Vampire Slayer (U)(Mode7)', '2003', 'Action', 'Natsume', '1', 'Action Adventure', 'Side-scrolling action brawler with platforming.', 'Stop the vampire threat and prevent the resurrection of Darkhul.', 'Protect Sunnydale as the Chosen One in this action-packed title.', 'Buffy The Vampire Slayer for GBA features tight controls and a faithful representation of the show''s dark tone. Slay demons, solve environmental puzzles, and save your friends from the forces of darkness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bura-bura-donkey-jcaravan', 'GAMEBOYADVANCE', 'Bura Bura Donkey (J)(Caravan)', '2002', 'Action', 'Caravan', '1', 'Action', 'Action-puzzle platformer with physics mechanics.', 'Guide Donkey Kong through stages by grabbing and swinging.', 'A unique "swinging" adventure featuring the Kong family.', 'Bura Bura Donkey (DK: King of Swing) redefines platforming. Instead of running, use the L and R buttons to control DK’s hands, swinging through levels and collecting medals in this creative and colorful Nintendo title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('butt-ugly-martians-bkm-battles-epatience', 'GAMEBOYADVANCE', 'Butt Ugly Martians BKM Battles (E)(Patience)', '2001', 'Action', 'Vicious Cycle Software', '1', 'Action Shooter', '2D side-scrolling shooter and action-adventure.', 'Defeat the alien invaders and protect Earth.', 'Join the Butt-Ugly Martians in their battle to save the planet.', 'Butt Ugly Martians BKM Battles is a high-energy action game based on the CGI series. Use futuristic weapons and flight suits to combat enemy drones and bosses across diverse planetary environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('butt-ugly-martians-bkm-battles-uvenom', 'GAMEBOYADVANCE', 'Butt Ugly Martians BKM Battles (U)(Venom)', '2001', 'Action', 'Vicious Cycle Software', '1', 'Action Shooter', '2D side-scrolling shooter and action-adventure.', 'Defeat the alien invaders and protect Earth.', 'Join the Butt-Ugly Martians in their battle to save the planet.', 'The US version of BKM Battles features fast-paced shooting and platforming. Choose your favorite Martian hero and master their unique combat skills to thwart Emperor Bog''s evil plans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cabbage-patch-kids---the-patch-puppy-rescue-esir-vg', 'GAMEBOYADVANCE', 'Cabbage Patch Kids - The Patch Puppy Rescue (E)(Sir VG)', '2006', 'Adventure', 'WayForward Technologies', '1', 'Adventure', 'Side-scrolling platformer with rescue objectives.', 'Navigate through the park to find and rescue all the lost puppies.', 'A sweet and colorful adventure for the Cabbage Patch Kids.', 'The Patch Puppy Rescue for GBA is a family-friendly game where you explore vibrant levels to find hidden puppies. Use simple platforming mechanics and interact with the environment in this charming classic toy adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cabbage-patch-kids---the-patch-puppy-rescue-utrashman', 'GAMEBOYADVANCE', 'Cabbage Patch Kids - The Patch Puppy Rescue (U)(Trashman)', '2006', 'Adventure', 'WayForward Technologies', '1', 'Adventure', 'Side-scrolling platformer with rescue objectives.', 'Navigate through the park to find and rescue all the lost puppies.', 'A sweet and colorful adventure for the Cabbage Patch Kids.', 'The US version of Patch Puppy Rescue offers accessible gameplay for younger fans. Explore different areas of the Cabbage Patch, collect items, and ensure every puppy makes it safely home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cabelas-big-game-hunter-uvenom', 'GAMEBOYADVANCE', 'Cabela''s Big Game Hunter (U)(Venom)', '2001', 'Sports', 'Sand Grain Studios', '1', 'Hunting', 'Hunting simulation with realistic environments.', 'Hunt various big game animals across North America.', 'A realistic and strategic outdoor hunting experience for GBA.', 'Cabela''s Big Game Hunter brings the thrill of the hunt to your handheld. Focus on stealth, scent management, and precision shooting as you track trophy animals in this detailed outdoor simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cabelas-big-game-hunter-2005-adventures-uvenom', 'GAMEBOYADVANCE', 'Cabela''s Big Game Hunter 2005 Adventures (U)(Venom)', '2004', 'Sports', 'Sand Grain Studios', '1', 'Hunting', 'Hunting simulation with realistic environments.', 'Complete specialized hunting missions and unlock new gear.', 'The expanded 2005 edition of the premier hunting series.', 'Cabela''s Big Game Hunter 2005 Adventures features more locations and improved ballistics. Master the art of tracking in diverse weather conditions and upgrade your equipment to bag the most elusive game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('caesars-palace-advance---millennium-gold-edition-umode7', 'GAMEBOYADVANCE', 'Caesar''s Palace Advance - Millennium Gold Edition (U)(Mode7)', '2001', 'Casino', 'Cosmic Concepts', '1', 'Casino', 'Collection of casino-style gambling games.', 'Win big at the slots, blackjack, and roulette to build your fortune.', 'Experience the thrill of the famous Caesar''s Palace on GBA.', 'Caesar''s Palace Advance offers a comprehensive casino experience. Test your luck and strategy in a variety of classic games, featuring realistic rules and a sophisticated Millennium Gold edition interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('calciobit-jwrg', 'GAMEBOYADVANCE', 'Calciobit (J)(WRG)', '2006', 'Sports', 'Skip Ltd.', '1', 'Sports', 'Soccer management and tactical simulation.', 'Lead your custom soccer club from the bottom to the top league.', 'A deep and charming Japanese soccer management sim.', 'Calciobit (Pocket League Story) is a highly addictive strategy game. Manage team training, scout for new talent, and make tactical decisions during matches to see your pixel-art team rise through the professional ranks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('camp-lazlo---leaky-lake-games-eindependent', 'GAMEBOYADVANCE', 'Camp Lazlo - Leaky Lake Games (E)(Independent)', '2006', 'Party', 'Vicarious Visions', '1', 'Party', 'Mini-game collection and adventure platforming.', 'Win the Leaky Lake Games to save the summer camp.', 'Join Lazlo and the Bean Scouts in a series of wacky challenges.', 'Camp Lazlo - Leaky Lake Games captures the humor of the Cartoon Network show. Participate in bizarre athletic events and explore the campsite to help Lazlo, Raj, and Clam defeat the rival Squirrel Scouts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('camp-lazlo-leaky-lake-games-urising-sun', 'GAMEBOYADVANCE', 'Camp Lazlo Leaky Lake Games (U)(Rising Sun)', '2006', 'Party', 'Vicarious Visions', '1', 'Party', 'Mini-game collection and adventure platforming.', 'Win the Leaky Lake Games to save the summer camp.', 'Join Lazlo and the Bean Scouts in a series of wacky challenges.', 'The US version of Camp Lazlo features various gameplay styles, from racing to puzzle-solving. Master each "sport" and enjoy the quirky character interactions that fans of the series love.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('capcom-classics---mini-mix-urising-sun', 'GAMEBOYADVANCE', 'Capcom Classics - Mini Mix (U)(Rising Sun)', '2006', 'Compilation', 'Capcom', '1', 'Classic Arcade', 'Collection of classic arcade hits.', 'Achieve high scores in legendary Capcom arcade titles.', 'Five Capcom classics: 1942, Ghosts ''n Goblins, and more in one.', 'Capcom Classics - Mini Mix is a retro goldmine. Experience faithful ports of Section Z, Bionic Commando, and Strider (NES version), offering a perfect blend of high-difficulty action and nostalgic arcade gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-tsubasa---eikou-no-kiseki-jcezar', 'GAMEBOYADVANCE', 'Captain Tsubasa - Eikou no Kiseki (J)(Cezar)', '2003', 'Sports', 'Tecmo', '1', 'Soccer', 'Tactical soccer RPG and card-based strategy.', 'Lead Tsubasa to victory in the international soccer tournament.', 'A strategic take on the legendary soccer anime and manga.', 'Captain Tsubasa - Eikou no Kiseki features a unique card-based system for match maneuvers. Plan your plays, use special "miracle" shots, and follow the dramatic story of Tsubasa Ozora on his quest for glory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('car-battler-joe-uvenom', 'GAMEBOYADVANCE', 'Car Battler Joe (U)(Venom)', '2002', 'RPG', 'Ancient', '1', 'Action RPG', 'Action-adventure with vehicular combat and RPG elements.', 'Build the ultimate combat vehicle and find your missing father.', 'A unique mix of car customization, exploration, and combat.', 'Car Battler Joe is a cult classic for the GBA. In a Mad Max-style world, scavenge for parts to upgrade your car, engage in tactical arena battles, and complete quests to uncover your family''s history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('card-captor---sakura-card-friends-jcezar', 'GAMEBOYADVANCE', 'Card Captor - Sakura Card Friends (J)(Cezar)', '2001', 'Adventure', 'TOSE', '1', 'Adventure', 'Visual novel and social simulation.', 'Help Sakura build friendships and collect Clow Cards.', 'A charming Japanese social adventure based on Cardcaptor Sakura.', 'Card Captor Sakura - Sakura Card Friends lets you experience the daily life of Sakura Kinomoto. Interact with iconic characters, participate in school events, and strengthen your bonds to unlock special story events in this faithful anime adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('card-captor-sakura---sakura-card-de-mini-game-jcezar', 'GAMEBOYADVANCE', 'Card Captor Sakura - Sakura Card de Mini Game (J)(Cezar)', '2001', 'Mini Games', 'TOSE', '1', 'Mini Games', 'Mini-game collection and puzzle action.', 'Master various magical challenges to capture Clow Cards.', 'A fun-filled variety of mini-games featuring Sakura and Kero.', 'Sakura Card de Mini Game offers a series of quick, magical challenges. From rhythm games to logic puzzles, each mission is designed around Sakura''s adventures, providing a colorful and accessible experience for fans of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('card-e-reader-jindependent', 'GAMEBOYADVANCE', 'Card e-Reader (J)(Independent)', '2002', 'Utility', 'Nintendo', '1', 'Peripheral', 'Hardware utility and digital card expansion.', 'Scan physical cards to unlock games, items, and levels.', 'The original peripheral software for the GBA Card e-Reader.', 'The Card e-Reader utility allows GBA owners to bridge the gap between physical trading cards and digital gameplay. Scan compatible cards to unlock classic NES games, new levels in Super Mario, or special items in various supported titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('card-e-reader-uindependent', 'GAMEBOYADVANCE', 'Card e-Reader (U)(Independent)', '2002', 'Utility', 'Nintendo', '1', 'Peripheral', 'Hardware utility and digital card expansion.', 'Scan physical cards to unlock games, items, and levels.', 'The US version of the innovative e-Reader peripheral software.', 'This US release of the Card e-Reader software is essential for accessing "e-card" exclusive content. It allows players to transform physical cards into interactive digital experiences, expanding the lifespan of many classic GBA titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('card-e-reader-+-jbatman', 'GAMEBOYADVANCE', 'Card e-Reader + (J)(BatMan)', '2003', 'Utility', 'Nintendo', '1', 'Peripheral', 'Hardware utility and digital card expansion.', 'Scan and store data from a wide variety of expansion cards.', 'The enhanced Japanese version of the e-Reader software.', 'Card e-Reader + features improved storage and compatibility. This Japanese utility is the definitive way to scan and enjoy massive amounts of digital content, from music tracks to entire mini-games hidden within physical cards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('card-party-jevasion', 'GAMEBOYADVANCE', 'Card Party (J)(Evasion)', '2001', 'Card', 'Game Freak', '1', 'Card Game', 'Digital card game and party simulation.', 'Be the first to empty your hand and win the tournament.', 'A collection of classic and original card games for party play.', 'Card Party for GBA offers a suite of engaging card games designed for quick sessions. Compete against AI or friends in various modes that test your strategy and luck in a fun, vibrant digital environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('care-bears---care-quest-utrashman', 'GAMEBOYADVANCE', 'Care Bears - Care Quest (U)(Trashman)', '2004', 'Adventure', 'Vicarious Visions', '1', 'Adventure', 'Side-scrolling platformer and puzzle-adventure.', 'Save Care-a-Lot by completing helpful quests for friends.', 'A sweet and colorful journey with the lovable Care Bears.', 'Care Bears - Care Quest is a family-friendly adventure where you play as different bears. Use each bear''s unique "Stare" power to solve puzzles, help characters in need, and restore happiness to the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('care-bears---the-care-quests-erising-sun', 'GAMEBOYADVANCE', 'Care Bears - The Care Quests (E)(Rising Sun)', '2004', 'Adventure', 'Vicarious Visions', '1', 'Adventure', 'Side-scrolling platformer and puzzle-adventure.', 'Save Care-a-Lot by completing helpful quests for friends.', 'A sweet and colorful journey with the lovable Care Bears.', 'The European version of The Care Quests offers accessible platforming and moral-based missions. Explore vibrant environments and master simple mini-games designed to teach cooperation and kindness to younger players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('carrera-power-slide-evenom', 'GAMEBOYADVANCE', 'Carrera Power Slide (E)(Venom)', '2004', 'Racing', 'Radical Entertainment', '4', 'Arcade Racing', 'Slot-car racing and arcade driving.', 'Outpace your rivals on winding slot-car tracks.', 'Fast-paced racing action based on the Carrera toy brand.', 'Carrera Power Slide brings the thrill of slot-car racing to the GBA. Master the acceleration physics to navigate tight turns without flying off the track, featuring multiple car classes and challenging circuits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cars-eindependent', 'GAMEBOYADVANCE', 'Cars (E)(Independent)', '2006', 'Racing', 'Helixe', '1', 'Arcade Racing', 'Racing and open-world mission adventure.', 'Help Lightning McQueen win the Piston Cup championship.', 'High-speed racing and mini-games based on the Disney/Pixar hit.', 'Cars for GBA lets you explore Radiator Springs and compete in intense races. Upgrade McQueen’s performance, participate in tractor tipping, and follow the movie''s heartwarming story in this polished handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cars-esupplex', 'GAMEBOYADVANCE', 'Cars (E)(sUppLeX)', '2006', 'Racing', 'Helixe', '1', 'Arcade Racing', 'Racing and open-world mission adventure.', 'Help Lightning McQueen win the Piston Cup championship.', 'High-speed racing and mini-games based on the Disney/Pixar hit.', 'This version of Cars features diverse gameplay styles, combining traditional racing with exploration. Master the drift mechanics and unlock new characters as you journey toward becoming a racing legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cars-grising-sun', 'GAMEBOYADVANCE', 'Cars (G)(Rising Sun)', '2006', 'Racing', 'Helixe', '1', 'Arcade Racing', 'Racing and open-world mission adventure.', 'Help Lightning McQueen win the Piston Cup championship.', 'The German-localized edition of the Pixar racing adventure.', 'Cars (German Version) brings the world of Lightning McQueen to life. Complete missions for Doc Hudson, Mater, and Sally while preparing for the final showdown at the Piston Cup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cars-iindependent', 'GAMEBOYADVANCE', 'Cars (I)(Independent)', '2006', 'Racing', 'Helixe', '1', 'Arcade Racing', 'Racing and open-world mission adventure.', 'Help Lightning McQueen win the Piston Cup championship.', 'The Italian-localized edition of the Pixar racing adventure.', 'Cars (Italian Version) delivers high-velocity fun on your GBA. Experience the charm of Radiator Springs and the thrill of professional racing in this faithful adaptation of the beloved animated film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cars-jwrg', 'GAMEBOYADVANCE', 'Cars (J)(WRG)', '2006', 'Racing', 'Helixe', '1', 'Arcade Racing', 'Racing and open-world mission adventure.', 'Help Lightning McQueen win the Piston Cup championship.', 'The Japanese-localized edition of the Pixar racing adventure.', 'Cars for GBA brings the cinematic racing experience to Japan. Featuring colorful graphics and intuitive controls, it’s a perfect pick for fans who want to relive the movie''s best moments on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cars-utrashman', 'GAMEBOYADVANCE', 'Cars (U)(Trashman)', '2006', 'Racing', 'Helixe', '1', 'Arcade Racing', 'Racing and open-world mission adventure.', 'Help Lightning McQueen win the Piston Cup championship.', 'The US version of the high-speed Disney/Pixar adventure.', 'The US release of Cars offers a robust racing experience with several playable characters. Master the desert tracks and participate in fun mini-games that capture the personality of the film’s cast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cars-mater-national-championship-esp', 'GAMEBOYADVANCE', 'Cars Mater-National Championship (E)(SP)', '2007', 'Racing', 'Incinerator Studios', '1', 'Arcade Racing', 'Racing and vehicular mini-game collection.', 'Compete in Mater''s international racing tournament.', 'A high-octane sequel featuring new tracks and international rivals.', 'Cars Mater-National Championship expands the racing world. Join Mater in a series of global challenges, featuring new playable characters and themed tracks that test your speed and precision driving.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cars-mater-national-championship-usir-vg', 'GAMEBOYADVANCE', 'Cars Mater-National Championship (U)(Sir VG)', '2007', 'Racing', 'Incinerator Studios', '1', 'Arcade Racing', 'Racing and vehicular mini-game collection.', 'Compete in Mater''s international racing tournament.', 'A high-octane sequel featuring new tracks and international rivals.', 'The US version of Mater-National Championship offers refined racing physics and a variety of game modes. Race through Radiator Springs and beyond in a quest for international racing glory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cartoon-network---block-party-uvenom', 'GAMEBOYADVANCE', 'Cartoon Network - Block Party (U)(Venom)', '2004', 'Party', 'High Voltage Software', '4', 'Party', 'Digital board game and mini-game collection.', 'Win the board game by outperforming rivals in mini-games.', 'Party with Johnny Bravo, Courage, and more Nick stars.', 'Cartoon Network - Block Party is the ultimate crossover for GBA. Choose your favorite character and navigate themed boards, competing in hilarious mini-games to earn points and win the tournament.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cartoon-network---speedway-uvenom', 'GAMEBOYADVANCE', 'Cartoon Network - Speedway (U)(Venom)', '2003', 'Racing', 'HBK', '1', 'Arcade Racing', 'Kart racing and vehicular combat.', 'Win the Speedway championship with Cartoon Network stars.', 'High-speed kart racing featuring your favorite animated icons.', 'Cartoon Network - Speedway lets you race as characters from Dexter''s Lab, Cow and Chicken, and more. Use wacky power-ups and master the drift to finish first in this vibrant and chaotic racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('casper-erocket', 'GAMEBOYADVANCE', 'Casper (E)(Rocket)', '2000', 'Action', 'Luma Arcade', '1', 'Action Platformer', 'Side-scrolling adventure and puzzle platformer.', 'Help Casper find his friends and complete ghostly tasks.', 'A charming and spooky adventure with the Friendly Ghost.', 'Casper for GBA features exploration-based gameplay where you use ghostly abilities to bypass obstacles. Navigate the manor, solve environmental puzzles, and avoid the Trio in this family-friendly title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('casper-uindependent', 'GAMEBOYADVANCE', 'Casper (U)(Independent)', '2000', 'Action', 'Luma Arcade', '1', 'Action Platformer', 'Side-scrolling adventure and puzzle platformer.', 'Help Casper find his friends and complete ghostly tasks.', 'A charming and spooky adventure with the Friendly Ghost.', 'The US version of Casper offers a balanced mix of platforming and logic puzzles. Explore diverse locations and use Casper''s unique transformations to save the day and prove he''s the friendliest ghost around.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---aria-of-sorrow---alfred-hack', 'GAMEBOYADVANCE', 'Castlevania - Aria of Sorrow - Alfred Hack', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Play as Alfred and master his unique alchemical combat.', 'A character-swap hack for the legendary Aria of Sorrow.', 'The Alfred Hack introduces the Alchemist from Circle of the Moon into Aria of Sorrow. Experience a fresh take on the castle exploration with a new move set and projectile-based combat strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---aria-of-sorrow---call-of-chaos', 'GAMEBOYADVANCE', 'Castlevania - Aria of Sorrow - Call of Chaos', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Survive a reimagined castle with increased difficulty.', 'A comprehensive gameplay overhaul hack for Aria of Sorrow.', 'Call of Chaos rebalances the entire game, offering new enemy placements, adjusted soul drop rates, and a significantly higher challenge level for veteran Castlevania players looking for a fresh experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---aria-of-sorrow---future-alucard-hack', 'GAMEBOYADVANCE', 'Castlevania - Aria of Sorrow - Future Alucard Hack', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Navigate the castle as Alucard in his modern gear.', 'A stylish character hack featuring the legendary dhampir.', 'Future Alucard Hack allows you to play through the 2035 setting using Alucard''s iconic moveset. Featuring updated sprites and adjusted stats, it bridges the gap between Symphony of the Night and the future era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---aria-of-sorrow---gebel-hack', 'GAMEBOYADVANCE', 'Castlevania - Aria of Sorrow - Gebel Hack', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Master Gebel''s ice magic to conquer Dracula''s castle.', 'A unique character hack featuring the antagonist from Bloodstained.', 'The Gebel Hack brings a modern touch to Aria of Sorrow. Play as the powerful shard-binder, utilizing his unique magical abilities to explore the castle and defeat the tactical soul system in a new way.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---aria-of-sorrow---genya-arikado-hack', 'GAMEBOYADVANCE', 'Castlevania - Aria of Sorrow - Genya Arikado Hack', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Explore the castle as the mysterious Genya Arikado.', 'A story-accurate character hack for Alucard''s undercover form.', 'Play as the powerful and stoic Genya Arikado in this fan-made modification. This hack features Alucard''s true power hidden behind his human facade, offering a more lore-friendly way to experience the events of 2035.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---aria-of-sorrow---hugh-baldwin-hack', 'GAMEBOYADVANCE', 'Castlevania - Aria of Sorrow - Hugh Baldwin Hack', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Use the power of the sword and whip as Hugh Baldwin.', 'A character-swap hack featuring the rival from Circle of the Moon.', 'The Hugh Baldwin Hack brings the technical sword-play of Circle of the Moon into the Aria of Sorrow engine. Master his unique combat style and explore the castle using a different tactical approach.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---aria-of-sorrow---julius-story-mode-hack', 'GAMEBOYADVANCE', 'Castlevania - Aria of Sorrow - Julius Story Mode Hack', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Follow Julius Belmont''s journey through the castle.', 'An expanded mode focusing on the legendary vampire hunter.', 'Julius Story Mode Hack enhances the secondary protagonist''s experience. With a full story progression and unique sub-weapon mechanics, it offers the definitive way to play as a Belmont in the year 2035.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---aria-of-sorrow---persephone-hack', 'GAMEBOYADVANCE', 'Castlevania - Aria of Sorrow - Persephone Hack', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Battle through the castle as the nimble Persephone.', 'A creative character hack featuring the iconic maid enemy.', 'The Persephone Hack lets you play as the fan-favorite enemy character. Featuring a unique vacuum-based attack and agile movement, it provides a quirky and surprisingly deep new way to navigate Dracula''s corridors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---aria-of-sorrow---reapers-reckoning', 'GAMEBOYADVANCE', 'Castlevania - Aria of Sorrow - Reaper''s Reckoning', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Reap the souls of the castle as the ultimate Death.', 'A powerful character hack where you play as the Grim Reaper.', 'Reaper''s Reckoning puts you in the scythe-wielding hands of Death himself. Use dark magic and massive physical attacks to tear through the castle''s defenses in this high-powered fan modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---aria-of-sorrow---zangetsu-hack', 'GAMEBOYADVANCE', 'Castlevania - Aria of Sorrow - Zangetsu Hack', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Hunt the darkness with the legendary samurai Zangetsu.', 'A crossover hack featuring the protagonist of Curse of the Moon.', 'The Zangetsu Hack brings a completely different combat feel to Aria of Sorrow. Use powerful katana techniques and elemental seals to purify the castle in this challenging and visually impressive modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---aria-of-sorrow-eeurasia', 'GAMEBOYADVANCE', 'Castlevania - Aria of Sorrow (E)(Eurasia)', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Absorb the souls of your enemies to stop the resurrection.', 'The masterpiece final GBA entry in the Castlevania series.', 'Castlevania: Aria of Sorrow introduces the "Tactical Soul" system. Play as Soma Cruz in the year 2035, exploring a futuristic eclipse-castle while collecting over 100 unique enemy abilities in one of the best GBA games ever made.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---aria-of-sorrow-ugbatemp', 'GAMEBOYADVANCE', 'Castlevania - Aria of Sorrow (U)(GBATemp)', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Absorb the souls of your enemies to stop the resurrection.', 'The masterpiece final GBA entry in the Castlevania series.', 'The US version of Aria of Sorrow features the acclaimed soul-collecting mechanic and deep RPG elements. Explore a massive interconnected world, battle epic bosses, and uncover the truth about Soma''s dark destiny.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---circle-of-the-moon---card-mode', 'GAMEBOYADVANCE', 'Castlevania - Circle Of The Moon - Card Mode', '2001', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG with magic card focus.', 'Defeat Dracula using a full deck of magical DSS cards.', 'A special mode for Circle of the Moon focusing on magic.', 'Castlevania - Circle Of The Moon - Card Mode grants the player all Dual Set-up System (DSS) cards from the start. Experiment with powerful elemental combinations and magical summons to conquer the castle in this strategic and high-power variant.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---circle-of-the-moon---hugh-baldwin-hack', 'GAMEBOYADVANCE', 'Castlevania - Circle Of The Moon - Hugh Baldwin Hack', '2001', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG with sword combat.', 'Explore the castle as the master swordsman Hugh Baldwin.', 'A character-swap hack featuring Nathan''s rival.', 'In the Hugh Baldwin Hack, play through Circle of the Moon with a completely different combat style. Trade the traditional whip for a fast-paced sword and unique sub-weapons, offering a fresh challenge for veteran vampire hunters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---circle-of-the-moon-eeurasia', 'GAMEBOYADVANCE', 'Castlevania - Circle of the Moon (E)(Eurasia)', '2001', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Slay the undead and seal Dracula within the castle walls.', 'The critically acclaimed debut of Castlevania on the GBA.', 'Castlevania - Circle of the Moon (European Version) features the innovative DSS card system. Explore a dark, atmospheric castle, battle iconic bosses, and master the whip in one of the most challenging and rewarding entries in the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---circle-of-the-moon-ucezar', 'GAMEBOYADVANCE', 'Castlevania - Circle of the Moon (U)(Cezar)', '2001', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Slay the undead and seal Dracula within the castle walls.', 'The critically acclaimed debut of Castlevania on the GBA.', 'Castlevania - Circle of the Moon (US Version) brings gothic horror to your handheld. Combine Action and Attribute cards to create over 80 unique magical effects while navigating a massive, secret-filled map.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---harmony-of-dissonance-eeurasia', 'GAMEBOYADVANCE', 'Castlevania - Harmony of Dissonance (E)(Eurasia)', '2002', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Hunt for the remains of Dracula in a dual-layered castle.', 'A fast-paced adventure featuring Juste Belmont.', 'Castlevania - Harmony of Dissonance (European Version) focuses on speed and flashy magic. Use the Spell Fusion system to combine sub-weapons with elemental books, creating devastating attacks in a sprawling, interconnected castle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---harmony-of-dissonance-uindependent', 'GAMEBOYADVANCE', 'Castlevania - Harmony of Dissonance (U)(Independent)', '2002', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Hunt for the remains of Dracula in a dual-layered castle.', 'A fast-paced adventure featuring Juste Belmont.', 'Castlevania - Harmony of Dissonance (US Version) stars Juste Belmont on a quest to save his friend Lydie. Explore two versions of the castle simultaneously, featuring vibrant graphics and intense, high-speed action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---maria-of-sorrow---easy', 'GAMEBOYADVANCE', 'Castlevania - Maria of Sorrow - Easy', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Save the world as Maria Renard with reduced difficulty.', 'A character hack featuring the legendary huntress on Easy mode.', 'Maria of Sorrow - Easy allows players to breeze through the castle using Maria''s unique animal-based attacks. With adjusted damage and higher health, it''s perfect for players who want to focus on exploration and Maria''s story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---maria-of-sorrow---normal', 'GAMEBOYADVANCE', 'Castlevania - Maria of Sorrow - Normal', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Save the world as Maria Renard with standard difficulty.', 'A character hack featuring the legendary huntress on Normal mode.', 'Maria of Sorrow - Normal replaces Soma Cruz with Maria Renard. Use her owls, cats, and dragons to fight through the castle, offering a completely different mechanical feel to the classic Aria of Sorrow gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---minuet-of-dawn-jeurasia', 'GAMEBOYADVANCE', 'Castlevania - Minuet Of Dawn (J)(Eurasia)', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Absorb the souls of your enemies to stop the resurrection.', 'The original Japanese release of Aria of Sorrow.', 'Castlevania - Minuet Of Dawn is the Japanese title for the acclaimed third GBA entry. Experience the deep Tactical Soul system and the futuristic setting of 2035 in its original, unedited format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---white-night-concerto-jeurasia', 'GAMEBOYADVANCE', 'Castlevania - White Night Concerto (J)(Eurasia)', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Hunt for the remains of Dracula in a dual-layered castle.', 'The original Japanese release of Harmony of Dissonance.', 'Castlevania - White Night Concerto stars Juste Belmont in a quest for the relics of Dracula. Experience the high-speed movement and complex Spell Fusion system of this classic GBA Metroidvania.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania-aria-of-sorrow---recolor-by-jonataguitar', 'GAMEBOYADVANCE', 'Castlevania Aria of Sorrow - Recolor by JonataGuitar', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Absorb souls in a castle with a vibrant new color palette.', 'A visual enhancement hack for Aria of Sorrow.', 'This Recolor hack by JonataGuitar updates the visual style of the game. Featuring improved saturation and color balance, it gives the 2035 setting a fresh, modern look without changing the legendary gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania-aria-of-sorrow-kaizo', 'GAMEBOYADVANCE', 'Castlevania Aria of Sorrow Kaizo', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Survive the ultimate challenge in a high-difficulty castle.', 'A brutal "Kaizo" style difficulty hack for Aria of Sorrow.', 'Castlevania Aria of Sorrow Kaizo is designed for masters of the game. Featuring redesigned rooms, aggressive enemy AI, and pixel-perfect platforming requirements, it is the ultimate test for any vampire hunter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania-dawn-of-symphony-alucard-sotn-hack', 'GAMEBOYADVANCE', 'Castlevania Dawn of Symphony (Alucard SOTN Hack)', '2003', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Explore the eclipse as Alucard with his SOTN moveset.', 'A massive hack bringing Alucard from Symphony of the Night.', 'Castlevania Dawn of Symphony transforms the game into a true Alucard experience. Featuring sprites and mechanics directly inspired by the PlayStation classic, it’s the ultimate crossover for series fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania-harmony-of-dissonance---recolor-by-jonataguitar-and-sorrow', 'GAMEBOYADVANCE', 'Castlevania Harmony of Dissonance - Recolor by JonataGuitar and sorrow', '2002', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Explore the castle with improved colors and Aria of Sorrow style.', 'A visual and stylistic overhaul for Harmony of Dissonance.', 'This Recolor hack fixes the bright, saturated colors of the original game to match the darker, more gothic tone of Aria of Sorrow, making for a much more atmospheric and visually pleasing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania-harmony-of-dissonance-music-overhaul', 'GAMEBOYADVANCE', 'Castlevania Harmony of Dissonance Music Overhaul', '2002', 'Action', 'Konami', '1', 'Metroidvania', 'Side-scrolling action-RPG (Metroidvania).', 'Hunt Dracula with an improved and high-quality soundtrack.', 'A technical hack that replaces the original''s MIDI music.', 'Harmony of Dissonance Music Overhaul addresses the game''s biggest criticism by replacing the low-quality sound files with high-fidelity tracks, bringing the audio quality up to the standards of the other GBA entries.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castleween-eeurasia', 'GAMEBOYADVANCE', 'Castleween (E)(Eurasia)', '2004', 'Action', 'Independent', '1', 'Action Platformer', 'Side-scrolling platformer with horror themes.', 'Rescue your friends from the clutches of the evil Bogeyman.', 'A spooky and fun platformer perfect for the Halloween season.', 'Castleween (known as Spirits & Spells in the US) features a charming gothic art style. Switch between Greg and Alicia, each with unique abilities, to navigate treacherous graveyards and haunted houses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('catwoman-uhyperion', 'GAMEBOYADVANCE', 'Catwoman (U)(Hyperion)', '2004', 'Action', 'EA UK', '1', 'Action Platformer', 'Third-person action-adventure and stealth.', 'Use your feline agility to pull off a series of high-stakes heists.', 'Play as the iconic anti-heroine in this movie-based adventure.', 'Catwoman for GBA features acrobatic movement and whip-based combat. Master the art of stealth to bypass security, solve environmental puzzles, and experience the thrill of the hunt in Gotham City.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('catz-erising-sun', 'GAMEBOYADVANCE', 'Catz (E)(Rising Sun)', '2003', 'Simulation', 'MTO', '1', 'Pet Simulation', 'Virtual pet simulation and animal care.', 'Raise, train, and play with your favorite breeds of kittens.', 'A cute and relaxing virtual pet game for cat lovers.', 'Catz for GBA allows you to adopt and care for a variety of adorable kittens. Feed them, groom them, and play mini-games to build a bond with your digital feline friends in this charming simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('catz-urising-sun', 'GAMEBOYADVANCE', 'Catz (U)(Rising Sun)', '2003', 'Simulation', 'MTO', '1', 'Pet Simulation', 'Virtual pet simulation and animal care.', 'Raise, train, and play with your favorite breeds of kittens.', 'The US version of the popular feline care simulator.', 'Catz (US Version) offers a portable sanctuary for cat enthusiasts. Customize your kittens with accessories and watch them grow as you provide them with a happy and healthy digital home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('centipede-breakout-warlords-esupplex', 'GAMEBOYADVANCE', 'Centipede, Breakout, Warlords (E)(Supplex)', '2005', 'Arcade', 'Atari', '4', 'Arcade Compilation', 'Arcade compilation of retro classics.', 'Achieve high scores in three legendary Atari arcade hits.', 'A 3-in-1 collection featuring Centipede, Breakout, and Warlords.', 'This Atari collection brings the golden age of arcades to your GBA. Battle insect hordes in Centipede, smash bricks in Breakout, and defend your castle in the frantic multiplayer-classic Warlords.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('centipede-breakout-warlords-utrashman', 'GAMEBOYADVANCE', 'Centipede, Breakout, Warlords (U)(Trashman)', '2005', 'Arcade', 'Atari', '4', 'Arcade Compilation', 'Arcade compilation of retro classics.', 'Achieve high scores in three legendary Atari arcade hits.', 'A 3-in-1 collection featuring Centipede, Breakout, and Warlords.', 'The US version of this classic compilation offers pixel-perfect gameplay. Test your reflexes across three distinct arcade genres, each with multiple difficulty settings and faithful retro sound effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chaoji-maliou-cwrg', 'GAMEBOYADVANCE', 'Chaoji Maliou (C)(WRG)', '2001', 'Platformer', 'Nintendo', '1', 'Platformer', '2D side-scrolling platformer (Mario-style).', 'Save the princess and defeat the turtle kingdom.', 'A Chinese-developed 8-bit style Mario clone for GBA.', 'Chaoji Maliou is a fascinating piece of bootleg history. It offers classic platforming gameplay reminiscent of Super Mario Bros., featuring familiar levels and mechanics adapted for the Game Boy Advance hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chaoji-maliou-shijie-cwrg', 'GAMEBOYADVANCE', 'Chaoji Maliou Shijie (C)(WRG)', '2001', 'Platformer', 'Nintendo', '1', 'Platformer', '2D side-scrolling platformer (Mario-style).', 'Explore the world and defeat the evil King Koopa.', 'A Chinese-developed Mario adventure featuring diverse levels.', 'Chaoji Maliou Shijie (Super Mario World) brings a unique take on the platforming legend. Navigate through various worlds, collect power-ups, and enjoy a retro-style adventure in this unlicensed Chinese release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('charlie-and-the-chocolate-factory-eindependent', 'GAMEBOYADVANCE', 'Charlie and the Chocolate Factory (E)(Independent)', '2005', 'Adventure', 'High Voltage Software', '1', 'Adventure', 'Action-adventure and mini-game collection.', 'Explore the factory and find the Great Glass Elevator.', 'A whimsical adventure based on the Tim Burton film.', 'Charlie and the Chocolate Factory for GBA lets you play as Charlie Bucket. Work with the Oompa-Loompas to solve puzzles, clean up the factory, and avoid the traps set for the other greedy children.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('charlie-and-the-chocolate-factory-utrashman', 'GAMEBOYADVANCE', 'Charlie and the Chocolate Factory (U)(Trashman)', '2005', 'Adventure', 'High Voltage Software', '1', 'Adventure', 'Action-adventure and mini-game collection.', 'Explore the factory and find the Great Glass Elevator.', 'A whimsical adventure based on the Tim Burton film.', 'The US version of Charlie and the Chocolate Factory features vibrant levels based on the movie''s iconic rooms. Master various mini-games and use clever platforming to prove you are the worthy heir to Wonka’s legacy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('charlottes-web-eindependent', 'GAMEBOYADVANCE', 'Charlotte''s Web (E)(Independent)', '2006', 'Adventure', 'Gravity-I', '1', 'Adventure', 'Side-scrolling adventure and mini-game collection.', 'Help Wilbur the pig win the blue ribbon at the county fair.', 'A heartwarming adventure based on the classic book and movie.', 'Charlotte''s Web for GBA features exploration and teamwork. Play as Wilbur and Templeton the rat to complete missions for Charlotte, solving puzzles and playing mini-games to ensure Wilbur''s safety.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('charlottes-web-urising-sun', 'GAMEBOYADVANCE', 'Charlotte''s Web (U)(Rising Sun)', '2006', 'Adventure', 'Gravity-I', '1', 'Adventure', 'Side-scrolling adventure and mini-game collection.', 'Help Wilbur the pig win the blue ribbon at the county fair.', 'A heartwarming adventure based on the classic book and movie.', 'The US version of Charlotte''s Web brings the farm to life. Navigate through beautiful 2D environments, help your animal friends, and experience the timeless story of friendship and bravery on your handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chessmaster-elightforce', 'GAMEBOYADVANCE', 'Chessmaster (E)(Lightforce)', '2002', 'Board Game', 'Software Toolworks', '2', 'Board Game', 'Strategic board game and chess simulation.', 'Defeat the grandmaster and improve your chess skills.', 'The definitive portable edition of the world''s most famous chess sim.', 'Chessmaster for GBA offers a robust chess engine for all skill levels. Featuring deep tutorials, multiple AI personalities, and a clean interface, it’s the perfect tool for both beginners and seasoned pros to practice on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chessmaster-fpatience', 'GAMEBOYADVANCE', 'Chessmaster (F)(Patience)', '2002', 'Board Game', 'Software Toolworks', '2', 'Board Game', 'Strategic board game and chess simulation.', 'Defeat the grandmaster and improve your chess skills.', 'The French-localized version of the premier chess simulator.', 'Chessmaster (French Version) provides a comprehensive set of challenges and training modes. Test your tactical wit against a variety of virtual opponents in this polished and intellectual strategy game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chessmaster-grising-sun', 'GAMEBOYADVANCE', 'Chessmaster (G)(Rising Sun)', '2002', 'Board Game', 'Software Toolworks', '2', 'Board Game', 'Strategic board game and chess simulation.', 'Defeat the grandmaster and improve your chess skills.', 'The German-localized version of the premier chess simulator.', 'Chessmaster (German Version) features the same high-quality chess engine. Analyze your moves, learn from past games, and climb the ranks of the professional chess world in this portable strategic masterclass.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chessmaster-ubatman', 'GAMEBOYADVANCE', 'ChessMaster (U)(BatMan)', '2002', 'Board Game', 'Software Toolworks', '2', 'Board Game', 'Strategic board game and chess simulation.', 'Defeat the grandmaster and improve your chess skills.', 'The US version of the comprehensive chess training software.', 'ChessMaster for GBA is a must-have for strategy fans. With over 20 different AI opponents and hundreds of classic match scenarios to analyze, it offers an endless amount of deep, intellectual gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chi-vuol-essere-milionario-iparanoid', 'GAMEBOYADVANCE', 'Chi Vuol Essere Milionario (I)(Paranoid)', '2000', 'Trivia', 'Sony Computer Entertainment', '1', 'Game Show', 'Trivia-based quiz game.', 'Answer 15 consecutive questions to win the virtual million.', 'The Italian edition of "Who Wants to Be a Millionaire?".', 'Chi Vuol Essere Milionario brings the tension of the hit TV show to your GBA. Use your lifelines (50:50, Phone a Friend, Ask the Audience) wisely to navigate through increasingly difficult questions and reach the final prize in this faithful Italian adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chicken-little-jsupplex', 'GAMEBOYADVANCE', 'Chicken Little (J)(sUppLeX)', '2005', 'Action Platformer', 'Altron', '1', 'Movie Tie-In', '2D action platformer and vehicle segments.', 'Help Chicken Little save the town from an alien invasion.', 'Join Chicken Little and friends in this colorful Disney adventure.', 'Chicken Little for GBA features a mix of running, jumping, and specialized vehicle levels. Play as Chicken Little, Runt, or Abby Mallard as you navigate through Oakey Oaks to prove the sky really is falling in this engaging movie-based title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chicken-little-utrashman', 'GAMEBOYADVANCE', 'Chicken Little (U)(Trashman)', '2005', 'Action Platformer', 'Altron', '1', 'Movie Tie-In', '2D action platformer and vehicle segments.', 'Help Chicken Little save the town from an alien invasion.', 'Join Chicken Little and friends in this colorful Disney adventure.', 'The US version of Chicken Little offers polished handheld platforming. Master various gadgets and dodge obstacles across levels inspired by the film, providing a fun and accessible experience for fans of the Disney/Pixar animation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chicken-shoot-erising-sun', 'GAMEBOYADVANCE', 'Chicken Shoot (E)(Rising Sun)', '2005', 'Shooter', 'FrontLine Studios', '1', 'Arcade Shooter', 'Point-and-click style shooting gallery.', 'Blast as many chickens as possible to earn high scores.', 'A quirky and fast-paced arcade shooter featuring crazy birds.', 'Chicken Shoot for GBA is a frantic gallery shooter. Use your crosshairs to hunt down mischievous chickens across various farm and village backdrops, featuring humorous animations and addictive, high-score driven gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chicken-shoot-uindependent', 'GAMEBOYADVANCE', 'Chicken Shoot (U)(Independent)', '2005', 'Shooter', 'FrontLine Studios', '1', 'Arcade Shooter', 'Point-and-click style shooting gallery.', 'Blast as many chickens as possible to earn high scores.', 'A quirky and fast-paced arcade shooter featuring crazy birds.', 'The US version of Chicken Shoot delivers arcade action on the go. Test your reflexes across multiple levels and difficulty settings as you try to stop the poultry takeover in this lighthearted and competitive shooting game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chicken-shoot-2-esir-vg', 'GAMEBOYADVANCE', 'Chicken Shoot 2 (E)(Sir VG)', '2006', 'Shooter', 'FrontLine Studios', '1', 'Arcade Shooter', 'Point-and-click style shooting gallery.', 'Clear the screen of chickens in new international locations.', 'The high-flying sequel with more levels and better graphics.', 'Chicken Shoot 2 expands the arcade experience with even more chaotic levels. Travel to exotic locations and use various power-ups to clear the screen of feathered foes in this fast-paced and funny handheld sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chicken-shoot-2-uindependent', 'GAMEBOYADVANCE', 'Chicken Shoot 2 (U)(Independent)', '2006', 'Shooter', 'FrontLine Studios', '1', 'Arcade Shooter', 'Point-and-click style shooting gallery.', 'Clear the screen of chickens in new international locations.', 'The high-flying sequel with more levels and better graphics.', 'The US version of Chicken Shoot 2 offers refined controls and new challenges. Compete for the highest score as you blast your way through diverse environments filled with hidden secrets and comical chicken animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chobits-jmugs', 'GAMEBOYADVANCE', 'Chobits (J)(MUGS)', '2003', 'Adventure', 'Digital Works', '1', 'Visual Novel', 'Visual novel and social simulation.', 'Build a relationship with the Persocon Chi and teach her about life.', 'A charming Japanese adventure based on the Chobits manga.', 'Chobits for GBA allows fans to experience the world of CLAMP''s famous series. Interact with Chi, participate in daily activities, and make choices that influence her personality and your bond in this beautifully illustrated Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chocobo-land---game-de-dice-jmugs', 'GAMEBOYADVANCE', 'Chocobo Land - Game de Dice (J)(Mugs)', '2002', 'Board Game', 'Squaresoft', '4', 'Dice Board Game', 'Digital board game with RPG elements.', 'Use dice to navigate the board and bankrupt your opponents.', 'A unique Final Fantasy spin-off starring the lovable Chocobo.', 'Chocobo Land - Game de Dice features strategic board-based gameplay. Acquire property, use magical spells, and summon classic Final Fantasy creatures to outmaneuver your rivals and dominate the map in this Japanese-exclusive gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('choh-makai-mura-r-jeurasia', 'GAMEBOYADVANCE', 'Choh Makai-Mura R (J)(Eurasia)', '2002', 'Action Platformer', 'Capcom', '1', 'Run and Gun', 'Hardcore side-scrolling action platformer.', 'Defeat the demons and save Princess Prin-Prin once again.', 'An enhanced GBA port of the legendary Super Ghouls ''n Ghosts.', 'Choh Makai-Mura R is the definitive handheld version of the Capcom classic. Featuring new levels and a branching path system, this Japanese release offers the same brutal difficulty and rewarding combat that fans of Arthur''s adventures love.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('choro-q-advance-jeurasia', 'GAMEBOYADVANCE', 'Choro Q Advance (J)(Eurasia)', '1999', 'Racing', 'Taito', '1', 'Toy Car Racing', 'Miniature car racing and customization.', 'Win races to earn parts and customize your Choro Q car.', 'A fun and deep RPG-style racer with tiny customizable cars.', 'Choro Q Advance (known as Gadget Racers) combines arcade racing with deep customization. Explore the world, compete in various events, and choose from hundreds of parts to build the perfect miniature vehicle for any terrain.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('choro-q-advance-2-jeurasia', 'GAMEBOYADVANCE', 'Choro Q Advance 2 (J)(Eurasia)', '2000', 'Racing', 'Taito', '1', 'Toy Car Racing', 'Miniature car racing and customization.', 'Become the champion of the Choro Q world in this expanded sequel.', 'More cars, more parts, and more tracks in this Japanese hit.', 'Choro Q Advance 2 builds upon its predecessor with refined handling and a larger world map. Engage in diverse racing challenges and manage your car''s stats to become the fastest racer in the Choro Q universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chu-chu-rocket!-eindependent', 'GAMEBOYADVANCE', 'Chu Chu Rocket! (E)(Independent)', '2001', 'Puzzle', 'Sonic Team', '4', 'Action Puzzle', 'Puzzle-solving and path management.', 'Guide the mice (ChuChus) to the rockets while avoiding cats.', 'A frantic and addictive puzzle classic from the Dreamcast era.', 'Chu Chu Rocket! for GBA is a perfect port of Sega''s chaotic puzzle hit. Place directional arrows on the floor to lead your mice to safety in both the intense single-player puzzle mode and the frantic 4-player battle mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chu-chu-rocket!-jcapital', 'GAMEBOYADVANCE', 'Chu Chu Rocket! (J)(Capital)', '2001', 'Puzzle', 'Sonic Team', '4', 'Action Puzzle', 'Puzzle-solving and path management.', 'Guide the mice (ChuChus) to the rockets while avoiding cats.', 'The Japanese version of the legendary Sega puzzle game.', 'This Japanese release of Chu Chu Rocket! features hundreds of brain-teasing puzzles. Master the art of tile placement to outsmart the KapuKapu cats and ensure all your mice make it to the escape rockets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chu-chu-rocket!-uthe-corporation', 'GAMEBOYADVANCE', 'Chu Chu Rocket! (U)(The Corporation)', '2001', 'Puzzle', 'Sonic Team', '4', 'Action Puzzle', 'Puzzle-solving and path management.', 'Guide the mice (ChuChus) to the rockets while avoiding cats.', 'The US version of the high-speed mouse-saving puzzle game.', 'Chu Chu Rocket! on the GBA delivers infinite replayability. With a built-in level editor and fast-paced "Battle" gameplay, it remains one of the most unique and challenging puzzle experiences on the handheld platform.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cima-the-enemy-umode7', 'GAMEBOYADVANCE', 'CIMA The Enemy (U)(Mode7)', '2003', 'Strategy', 'Neverland', '1', 'Tactical RPG', 'Isometric tactical RPG with squad management.', 'Protect the innocent and lead your team through hostile territory.', 'A deep and strategic RPG featuring the "CIMA" rescue system.', 'CIMA The Enemy offers a unique take on the RPG genre. Instead of just fighting, you must protect and guide a group of survivors through dangerous dungeons, managing their safety and morale while uncovering a dark alien conspiracy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cinderella---magical-dreams-esupplex', 'GAMEBOYADVANCE', 'Cinderella - Magical Dreams (E)(sUppLeX)', '2005', 'Adventure', 'Disney Interactive', '1', 'Fantasy Adventure', 'Side-scrolling adventure and mini-game collection.', 'Help Cinderella prepare for the ball and find her True Love.', 'A magical Disney adventure featuring the iconic glass slipper.', 'Cinderella - Magical Dreams brings the classic fairy tale to GBA. Explore the chateau, complete tasks for the Fairy Godmother, and avoid the wicked stepmother in a series of beautifully animated platforming levels and puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cinnamon---yume-no-daibouken-jcaravan', 'GAMEBOYADVANCE', 'Cinnamon - Yume no Daibouken (J)(Caravan)', '2004', 'Adventure', 'Interchannel', '1', 'Anime Adventure', 'Social simulation and mini-game adventure.', 'Help Cinnamon and the Cinnamoroll friends on a big quest.', 'A cute and relaxing Japanese adventure with Sanrio characters.', 'Cinnamon - Yume no Daibouken is a delightful experience for fans of Cinnamoroll. Navigate colorful environments, interact with friendly characters, and complete simple, fun tasks in this heartwarming Japanese-exclusive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cinnamon-fuwafuwa-daisakusen-jsupplex', 'GAMEBOYADVANCE', 'Cinnamon Fuwafuwa Daisakusen (J)(sUppLeX)', '2004', 'Action', 'Sonic Powered', '1', 'Anime Action', 'Mini-game collection and social simulation.', 'Complete various fluffy missions to keep everyone happy.', 'More adorable adventures with the Cinnamoroll gang.', 'Cinnamon Fuwafuwa Daisakusen features a variety of casual mini-games themed around the world of Sanrio. Perfect for younger players, it offers a safe and charming environment filled with cute characters and relaxing gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cinnamoroll-kokoniiruyo-jrising-sun', 'GAMEBOYADVANCE', 'Cinnamoroll Kokoniiruyo (J)(Rising Sun)', '2003', 'Adventure', 'Interchannel', '1', 'Anime Adventure', 'Social simulation and pet care.', 'Take care of your Cinnamoroll friend and build a lasting bond.', 'A portable virtual friend experience starring Cinnamoroll.', 'Cinnamoroll Kokoniiruyo focuses on the daily interaction with your favorite Sanrio puppy. Feed, play, and talk to Cinnamoroll as you build a friendship that grows over time in this cozy Japanese handheld game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('classic-nes---bomberman-upsychosis', 'GAMEBOYADVANCE', 'Classic Nes - Bomberman (U)(Psychosis)', '2004', 'Action', 'Hudson Soft', '2', 'Classic Arcade', 'Top-down action and bomb-laying strategy.', 'Defeat all enemies on screen to advance to the next level.', 'The pixel-perfect NES original reborn for the GBA.', 'Classic NES - Bomberman brings the 8-bit classic to your pocket. Relive the simple yet addictive gameplay of laying bombs, finding power-ups, and clearing stages in this faithful recreation of the game that started it all.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('classic-nes---castlevania-ubatman', 'GAMEBOYADVANCE', 'Classic NES - Castlevania (U)(BatMan)', '2004', 'Action', 'Konami', '1', 'Classic Platformer', 'Side-scrolling action platformer.', 'Enter Dracula''s castle and defeat the Lord of Darkness.', 'The legendary NES original that launched the franchise.', 'Classic NES - Castlevania allows you to experience Simon Belmont''s first quest on the go. Master the whip and sub-weapons to battle through iconic stages and bosses in this challenging and authentic 8-bit port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('classic-nes---donkey-kong-uhyperion', 'GAMEBOYADVANCE', 'Classic Nes - Donkey Kong (U)(Hyperion)', '2004', 'Platformer', 'Nintendo', '1', 'Classic Platformer', 'Single-screen platforming and arcade action.', 'Help Mario rescue Pauline from the giant ape.', 'The arcade and NES masterpiece on your handheld.', 'Classic NES - Donkey Kong features all the iconic levels of the original. Dodge barrels, climb ladders, and time your jumps perfectly to reach the top in this definitive port of one of gaming''s most important titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('classic-nes---excite-bike-upsychosis', 'GAMEBOYADVANCE', 'Classic Nes - Excite Bike (U)(Psychosis)', '2004', 'Racing', 'Nintendo', '1', 'Classic Racing', 'Side-scrolling motocross racing.', 'Reach the finish line as fast as possible without overheating.', 'The high-flying NES racing classic on the GBA.', 'Classic NES - Excite Bike brings the thrill of motocross to your handheld. Master the terrain, manage your engine temperature, and create your own tracks in the iconic Design Mode in this pixel-perfect retro port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('classic-nes---ice-climber-uhyperion', 'GAMEBOYADVANCE', 'Classic Nes - Ice Climber (U)(Hyperion)', '2004', 'Platformer', 'Nintendo', '2', 'Classic Platformer', 'Vertical-scrolling platformer and puzzle action.', 'Scale the mountain and reclaim the stolen vegetables.', 'The cooperative NES classic featuring Popo and Nana.', 'Classic NES - Ice Climber challenges you to reach the summit by breaking through ice ceilings. Avoid falling and dodge pesky creatures in this authentic 8-bit recreation of the vertical-climbing favorite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('classic-nes---metroid-ubatman', 'GAMEBOYADVANCE', 'Classic NES - Metroid (U)(BatMan)', '2004', 'Action Adventure', 'Nintendo', '1', 'Classic Exploration', 'Side-scrolling action-adventure (Metroidvania).', 'Navigate Planet Zebes and destroy Mother Brain.', 'The groundbreaking NES adventure that defined a genre.', 'Classic NES - Metroid brings Samus Aran''s original mission to the GBA. Explore a non-linear world, find power-ups like the Morph Ball and Missiles, and experience the atmospheric 8-bit exploration that started the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('classic-nes---pacman-uhyperion', 'GAMEBOYADVANCE', 'Classic Nes - Pacman (U)(Hyperion)', '2004', 'Action', 'Namco', '1', 'Classic Arcade', 'Maze-based arcade action.', 'Eat all the dots while avoiding the four ghosts.', 'The world''s most famous arcade game in the palm of your hand.', 'Classic NES - Pacman is a faithful port of the 8-bit home version. Master the patterns, collect power pellets to turn the tables on Blinky, Pinky, Inky, and Clyde, and chase high scores in this timeless classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('classic-nes---xevious-uhyperion', 'GAMEBOYADVANCE', 'Classic Nes - Xevious (U)(Hyperion)', '2004', 'Shooter', 'Namco', '1', 'Classic Shooter', 'Vertical-scrolling shoot ''em up (Shmup).', 'Destroy the GAMP forces and protect Earth.', 'The legendary 8-bit shooter from the NES era.', 'Classic NES - Xevious features the dual-attack gameplay of the original. Use your front-facing lasers for flying enemies and your ground bombs for structures in this pixel-perfect recreation of one of the first cinematic shooters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cocoto---kart-racer-eindependent', 'GAMEBOYADVANCE', 'Cocoto - Kart Racer (E)(Independent)', '2005', 'Racing', 'Neko Entertainment', '4', 'Cart Racing', 'Kart racing and vehicular combat.', 'Win the championship using Cocoto and his magical friends.', 'A vibrant and quirky kart racer featuring unique characters.', 'Cocoto - Kart Racer offers fast-paced racing across colorful fantasy tracks. Use diverse power-ups and master each character''s unique vehicle stats to come out on top in this competitive and family-friendly GBA racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cocoto-platform-jumper-eindependent', 'GAMEBOYADVANCE', 'Cocoto Platform Jumper (E)(Independent)', '2006', 'Platformer', 'Neko Entertainment', '1', 'Platform Jumper', '2D side-scrolling platformer.', 'Jump through various levels and defeat enemies to save the world.', 'A classic-style platformer starring the little devil Cocoto.', 'Cocoto Platform Jumper features challenging levels filled with traps and secrets. Use Cocoto''s abilities to navigate dangerous environments and battle massive bosses in this polished and vibrant 2D adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('code-breaker-uindependent', 'GAMEBOYADVANCE', 'Code Breaker (U)(Independent)', '2000', 'Action', 'Codemaster', '1', 'Top-Down Shooter', 'Game enhancement and cheat utility.', 'Unlock secret features and infinite lives in GBA games.', 'The famous cheat device software for Game Boy Advance.', 'Code Breaker is the essential utility for GBA power users. Access a massive database of cheat codes to unlock hidden levels, infinite health, and secret characters across hundreds of compatible titles on your handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('codename---kids-next-door---operation-soda-urising-sun', 'GAMEBOYADVANCE', 'Codename - Kids Next Door - Operation S.O.D.A. (U)(Rising Sun)', '2004', 'Action Platformer', 'Creative Capers', '1', 'Cartoon Action', 'Side-scrolling action platformer.', 'Defeat the adults and recover the secret soda recipe.', 'Join the KND in a high-stakes mission based on the hit show.', 'Codename: Kids Next Door - Operation S.O.D.A. lets you control all five operatives, each with unique gadgets and abilities. Navigate through treacherous 2D levels and use tactical teamwork to thwart the plans of the adult villains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('colin-mcrae-rally-2-ubatman', 'GAMEBOYADVANCE', 'Colin McRae Rally 2 (U)(BatMan)', '2001', 'Racing', 'Codemaster', '1', 'Rally Simulation', 'Isometric pseudo-3D rally racing.', 'Win the world rally championship across various terrains.', 'Experience intense rally racing with impressive 3D effects.', 'Colin McRae Rally 2 brings realistic physics and high-speed driving to the GBA. Master drifting on gravel, snow, and mud in diverse international stages, featuring a robust damage system and multiple licensed vehicles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('colin-mcrae-rally-20-equartex', 'GAMEBOYADVANCE', 'Colin McRae Rally 2.0 (E)(QUARTEX)', '2001', 'Racing', 'Codemaster', '1', 'Rally Simulation', 'Isometric pseudo-3D rally racing.', 'Win the world rally championship across various terrains.', 'Experience intense rally racing with impressive 3D effects.', 'The European version of Colin McRae Rally 2.0 offers precision handling and detailed environments. Compete in Time Trials or full Season modes to prove you are the fastest rally driver in the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('columns-crown-emenace', 'GAMEBOYADVANCE', 'Columns Crown (E)(Menace)', '2002', 'Puzzle', 'Sega', '2', 'Classic Puzzle', 'Falling-block match-three puzzle.', 'Align three or more identical gems to clear the board.', 'A portable and vibrant update to the classic Sega puzzle hit.', 'Columns Crown revitalizes the legendary puzzle series with new power-ups and competitive modes. Use magical items to sabotage your opponents and master the strategic gem-stacking gameplay that fans have loved for decades.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('columns-crown-jcezar', 'GAMEBOYADVANCE', 'Columns Crown (J)(Cezar)', '2002', 'Puzzle', 'Sega', '2', 'Classic Puzzle', 'Falling-block match-three puzzle.', 'Align three or more identical gems to clear the board.', 'The original Japanese release of the gem-matching classic.', 'This Japanese version of Columns Crown features colorful anime-style characters and intense puzzle action. Solve various challenges and climb the rankings in this addictive and visually polished GBA puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('columns-crown-ulord-moyne', 'GAMEBOYADVANCE', 'Columns Crown (U)(Lord Moyne)', '2002', 'Puzzle', 'Sega', '2', 'Classic Puzzle', 'Falling-block match-three puzzle.', 'Align three or more identical gems to clear the board.', 'The US version of Sega''s high-speed gem-matching puzzle.', 'Columns Crown (US Version) delivers smooth puzzle gameplay and catchy music. Perfect for quick sessions, it offers both a deep single-player quest and frantic multiplayer battles via the Link Cable.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('combat-choro-q---advance-battle-jindependent', 'GAMEBOYADVANCE', 'Combat Choro Q - Advance Battle (J)(Independent)', '1999', 'Action', 'Taito', '1', 'Toy Combat', 'Tactical tank-based strategy and combat.', 'Command your Choro Q tanks to victory in arena battles.', 'A strategic spin-off of the Choro Q series featuring tiny tanks.', 'Combat Choro Q - Advance Battle combines tank customization with grid-based strategy. Collect parts, upgrade your miniature tank''s armor and weaponry, and outmaneuver rivals in this engaging Japanese tactical title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('comix-zone-eindependent', 'GAMEBOYADVANCE', 'Comix Zone (E)(Independent)', '2002', 'Action Platformer', 'Sega', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up inside a comic book.', 'Fight your way through the pages to defeat the creator.', 'A visually stunning port of the legendary Sega Genesis hit.', 'Comix Zone brings the unique "comic book" aesthetic to GBA. Jump between panels, fight sketched enemies, and solve environmental puzzles in this stylized and challenging action classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('connect-four-perfection-trouble-utrashman', 'GAMEBOYADVANCE', 'Connect Four, Perfection, Trouble (U)(Trashman)', '2004', 'Board Game', 'Hasbro Interactive', '4', 'Party Board Game', 'Collection of classic tabletop board games.', 'Win matches in Connect Four, Perfection, and Trouble.', 'A 3-in-1 pack of Hasbro''s most popular board games.', 'This board game collection offers faithful digital recreations of three family favorites. Test your speed in Perfection, your strategy in Connect Four, and your luck in Trouble, all in one convenient GBA cartridge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('contra-advance---the-alien-wars-ex-eeternity', 'GAMEBOYADVANCE', 'Contra Advance - The Alien Wars Ex (E)(Eternity)', '2002', 'Run and Gun', 'Konami', '1', 'Arcade Shooter', 'Run-and-gun side-scrolling action.', 'Defeat the alien invasion and save humanity.', 'A hardcore action compilation featuring levels from Contra III.', 'Contra Advance - The Alien Wars Ex is the ultimate handheld challenge. Fight through intense stages filled with massive bosses and relentless enemies, combining the best of the 16-bit classic with new GBA-exclusive content.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('contra-advance---the-alien-wars-ex-umode7', 'GAMEBOYADVANCE', 'Contra Advance - The Alien Wars EX (U)(Mode7)', '2002', 'Run and Gun', 'Konami', '1', 'Arcade Shooter', 'Run-and-gun side-scrolling action.', 'Defeat the alien invasion and save humanity.', 'A hardcore action compilation featuring levels from Contra III.', 'The US version of Contra Advance delivers high-octane shooting and precision platforming. Master diverse weapons and survive legendary set-pieces in this definitive portable run-and-gun experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('contra-hard-spirits-jcezar', 'GAMEBOYADVANCE', 'Contra Hard Spirits (J)(Cezar)', '2002', 'Run and Gun', 'Konami', '1', 'Arcade Shooter', 'Run-and-gun side-scrolling action.', 'Defeat the alien invasion and save humanity.', 'The original Japanese release of the intense Alien Wars EX.', 'Contra Hard Spirits (Japanese Version) offers the same brutal difficulty and fast-paced gameplay. Experience the cinematic action and legendary soundtrack that made the Contra series a household name.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('corvette-uindependent', 'GAMEBOYADVANCE', 'Corvette (U)(Independent)', '2003', 'Racing', 'Titus', '1', 'Arcade Racing', 'Arcade racing and driving simulation.', 'Race through the streets in various classic Corvette models.', 'Celebrate 50 years of the iconic American sports car.', 'Corvette for GBA lets you pilot legendary vehicles across several decades of automotive history. Navigate diverse tracks, upgrade your performance, and master the handling of these high-performance machines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-advance-iv', 'GAMEBOYADVANCE', 'Crash Advance IV', '2004', 'Platformer', 'Vicarious Visions', '1', 'Platform Adventure', 'Side-scrolling platformer.', 'Stop Dr. Neo Cortex and collect all the hidden crystals.', 'A fan-made or unofficial continuation of the Crash series.', 'Crash Advance IV offers classic platforming action inspired by the original trilogy. Navigate treacherous environments, break crates, and use Crash''s signature spin attack to defeat enemies in this nostalgic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot---purple-riptos-rampage-uvenom', 'GAMEBOYADVANCE', 'Crash Bandicoot - Purple Ripto''s Rampage (U)(Venom)', '2005', 'Action Adventure', 'Vicarious Visions', '1', 'Crossover Adventure', 'Isometric adventure and mini-game crossover.', 'Stop the combined threat of Cortex and Ripto.', 'Crash meets Spyro in this unique handheld crossover.', 'Crash Bandicoot - Purple Ripto''s Rampage features a variety of mini-games and platforming segments. Team up with Spyro the Dragon to stop a cross-dimensional plot, featuring vibrant graphics and diverse gameplay challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot---the-huge-adventure-uindependent', 'GAMEBOYADVANCE', 'Crash Bandicoot - The Huge Adventure (U)(Independent)', '2002', 'Platformer', 'Vicarious Visions', '1', 'Platform Adventure', 'Side-scrolling platformer with 3D-style levels.', 'Recover the crystals and stop Cortex''s new space station.', 'The first original Crash Bandicoot adventure for the GBA.', 'Crash Bandicoot - The Huge Adventure (XS) faithfully recreates the console experience. Enjoy 2D platforming, chase sequences, and jetpack levels that look and play like the PlayStation classics on your handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-2-n-tranced-epatience', 'GAMEBOYADVANCE', 'Crash Bandicoot 2 N-Tranced (E)(Patience)', '2003', 'Platformer', 'Vicarious Visions', '1', 'Platform Adventure', 'Side-scrolling platformer with 3D-style levels.', 'Rescue your friends from N-Trance''s hypnotic control.', 'The polished sequel to Crash''s first GBA outing.', 'Crash Bandicoot 2: N-Tranced features improved graphics and new gameplay mechanics. Play as Crash, Coco, and Crunch as you navigate through time and space to stop the master of hypnotism.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-2-n-tranced-unoitami', 'GAMEBOYADVANCE', 'Crash Bandicoot 2 N-Tranced (U)(Noitami)', '2003', 'Platformer', 'Vicarious Visions', '1', 'Platform Adventure', 'Side-scrolling platformer with 3D-style levels.', 'Rescue your friends from N-Trance''s hypnotic control.', 'The polished sequel to Crash''s first GBA outing.', 'The US version of N-Tranced offers a deep platforming experience with secret paths and challenging relics. Master the slide-jump and spin attacks to uncover every hidden gem in this high-quality GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-advance---wakuwaku-tomodachi-daisakusen-jcaravan', 'GAMEBOYADVANCE', 'Crash Bandicoot Advance - Wakuwaku Tomodachi Daisakusen (J)(Caravan)', '2002', 'Platformer', 'Vicarious Visions', '1', 'Platform Adventure', 'Isometric adventure and mini-game crossover.', 'Stop the combined threat of Cortex and Ripto.', 'The Japanese version of the Crash and Spyro crossover.', 'Wakuwaku Tomodachi Daisakusen brings the "Purple" adventure to Japan. Experience the unique interaction between the two mascot legends through a series of fun and challenging mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-advance-jindependent', 'GAMEBOYADVANCE', 'Crash Bandicoot Advance (J)(Independent)', '2002', 'Platformer', 'Vicarious Visions', '1', 'Platform Adventure', 'Side-scrolling platformer with 3D-style levels.', 'Recover the crystals and stop Cortex''s new space station.', 'The original Japanese release of The Huge Adventure.', 'Crash Bandicoot Advance delivers the classic "Naughty Dog" style gameplay on a portable screen. Battle iconic bosses and master the time trials in this impressive technical showcase for the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-advance-2---gurugurusaimin-dai-panic-jrising-sun', 'GAMEBOYADVANCE', 'Crash Bandicoot Advance 2 - Gurugurusaimin Dai Panic (J)(Rising Sun)', '2004', 'Platformer', 'Vicarious Visions', '1', 'Platform Adventure', 'Side-scrolling platformer with 3D-style levels.', 'Rescue your friends from N-Trance''s hypnotic control.', 'The original Japanese release of the N-Tranced sequel.', 'Crash Bandicoot Advance 2 features the same high-energy platforming and vibrant art style. Collect every crystal and gem to unlock the secret ending in this definitive handheld sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-bakusou!-nitro-kart-jcaravan', 'GAMEBOYADVANCE', 'Crash Bandicoot Bakusou! Nitro Kart (J)(Caravan)', '2004', 'Racing', 'Vicarious Visions', '4', 'Arcade Kart Racing', 'Kart racing and vehicular combat.', 'Defeat Emperor Velo XXVII and save Earth from destruction.', 'The Japanese version of the high-speed racing sequel.', 'Bakusou! Nitro Kart brings the thrill of Crash racing to Japan. Master the power-slide mechanic, utilize crazy weapons, and race through gravity-defying tracks in this visually stunning GBA racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-fusion-erising-sun', 'GAMEBOYADVANCE', 'Crash Bandicoot Fusion (E)(Rising Sun)', '2004', 'Action RPG', 'Vivendi Universal', '1', 'Crossover RPG', 'Isometric adventure and mini-game crossover.', 'Stop the combined threat of Cortex and Ripto.', 'The European version of the Crash and Spyro crossover.', 'Crash Bandicoot Fusion allows players to explore a variety of themed worlds. Connect with the Spyro version of the game to unlock exclusive content and trade cards in this expansive handheld social title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-xs-eparacox', 'GAMEBOYADVANCE', 'Crash Bandicoot XS (E)(Paracox)', '2002', 'Platformer', 'Vicarious Visions', '1', 'Platform Adventure', 'Side-scrolling platformer with 3D-style levels.', 'Recover the crystals and stop Cortex''s new space station.', 'The European version of The Huge Adventure.', 'Crash Bandicoot XS (as known in Europe) is a masterclass in portable platforming. Featuring levels inspired by the first three PS1 games, it offers a nostalgic and challenging experience for fans of the orange marsupial.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-nitro-kart-erising-sun', 'GAMEBOYADVANCE', 'Crash Nitro Kart (E)(Rising Sun)', '2003', 'Racing', 'Vicarious Visions', '4', 'Arcade Kart Racing', 'Kart racing and vehicular combat.', 'Defeat Emperor Velo XXVII and save Earth from destruction.', 'The US version of the high-speed racing sequel.', 'Crash Nitro Kart features a deep adventure mode, multiple playable teams, and intense multiplayer action. Master the unique "Team Frenzy" mechanic and conquer the galactic race tracks to prove your skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-of-the-titans-esupplex', 'GAMEBOYADVANCE', 'Crash of the Titans (E)(sUppLeX)', '2007', 'Action Platformer', 'Amaze Entertainment', '1', 'Beat ''em Up', 'Action-adventure and brawler with "jacking" mechanics.', 'Hijack massive Titans to stop Cortex''s latest scheme.', 'A unique reimagining of the Crash series with combat focus.', 'Crash of the Titans for GBA introduces the ability to control powerful mutant enemies. Use their unique strengths to solve puzzles and defeat waves of foes in this high-energy, combat-oriented platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-of-the-titans-uomgba', 'GAMEBOYADVANCE', 'Crash of the Titans (U)(OMGba)', '2007', 'Action Platformer', 'Amaze Entertainment', '1', 'Beat ''em Up', 'Action-adventure and brawler with "jacking" mechanics.', 'Hijack massive Titans to stop Cortex''s latest scheme.', 'A unique reimagining of the Crash series with combat focus.', 'The US version of Crash of the Titans offers fluid brawling action and impressive character animations. Explore diverse environments and master the "Mojo" system to upgrade Crash''s abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crayon-shin-chan---densetsu-wo-yobu-omake-no-miyako-shockgaan-jindependent', 'GAMEBOYADVANCE', 'Crayon Shin chan - Densetsu wo Yobu Omake no Miyako Shockgaan (J)(Independent)', '2004', 'Adventure', 'Banpresto', '1', 'Anime Adventure', 'Side-scrolling action platformer.', 'Navigate through wacky levels based on the Shin-chan anime.', 'A colorful and hilarious Japanese adventure starring Shin-chan.', 'Shockgaan features the signature humor and art style of the Crayon Shin-chan series. Use various costumes to gain new abilities and overcome bizarre obstacles in this charming Japanese-exclusive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crayon-shin-chan---arashi-no-yobu-cinema-land-no-daibouken!-jtrashman', 'GAMEBOYADVANCE', 'Crayon Shin-Chan - Arashi no Yobu Cinema-Land no Daibouken! (J)(TrashMan)', '2004', 'Adventure', 'Banpresto', '1', 'Anime Adventure', 'Action-adventure and mini-game collection.', 'Experience the magic of the movies in Cinema-Land.', 'A movie-themed Shin-chan adventure for the GBA.', 'Arashi no Yobu Cinema-Land takes Shin-chan through levels inspired by different film genres. Participate in wacky mini-games and enjoy the irreverent comedy that makes this series a fan favorite in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-chase-epatience', 'GAMEBOYADVANCE', 'Crazy Chase (E)(Patience)', '2003', 'Action', 'Patience', '1', 'Top-Down Action', 'Isometric obstacle-course runner.', 'Chase the prince and reach the goal before time runs out.', 'A vibrant and quirky isometric racing-action game.', 'Crazy Chase (Kid Klown) features frantic gameplay where you must avoid traps and obstacles in a 2.5D environment. Master the timing of your jumps and dashes to recover the stolen crown in this colorful handheld port of the SNES classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-chase-uevasion', 'GAMEBOYADVANCE', 'Crazy Chase (U)(Evasion)', '2003', 'Action', 'Evasion', '1', 'Top-Down Action', 'Isometric obstacle-course runner.', 'Chase the prince and reach the goal before time runs out.', 'A vibrant and quirky isometric racing-action game.', 'The US version of Crazy Chase delivers fast-paced, slapstick humor. Navigate through diverse levels filled with unexpected hazards, utilizing quick reflexes to stay ahead of the clock in this unique and challenging arcade runner.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-frog-racer-erising-sun', 'GAMEBOYADVANCE', 'Crazy Frog Racer (E)(Rising Sun)', '2005', 'Racing', 'Neko Entertainment', '4', 'Arcade Racing', 'Kart racing with power-ups and weapons.', 'Win the race and cause chaos as the "Annoying Thing."', 'High-speed kart racing featuring the world-famous Crazy Frog.', 'Crazy Frog Racer for GBA brings the viral character to the track. Use a variety of wacky weapons and speed boosts to outpace your rivals across several themed circuits in this colorful and loud handheld racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-taxi---catch-a-ride-etrashman', 'GAMEBOYADVANCE', 'Crazy Taxi - Catch A Ride (E)(Trashman)', '2003', 'Action', 'Neko Entertainment', '1', 'Arcade Driving', 'Arcade driving and mission-based transport.', 'Pick up passengers and deliver them as fast as possible.', 'The legendary Sega arcade hit reimagined for the GBA.', 'Crazy Taxi - Catch A Ride brings the high-octane "crazy" driving to your pocket. Master the Crazy Drift and Crazy Dash to navigate city streets, dodging traffic and finding shortcuts to maximize your tips and score.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-taxi---catch-a-ride-uvenom', 'GAMEBOYADVANCE', 'Crazy Taxi - Catch a Ride (U)(Venom)', '2003', 'Action', 'Neko Entertainment', '1', 'Arcade Driving', 'Arcade driving and mission-based transport.', 'Pick up passengers and deliver them as fast as possible.', 'The legendary Sega arcade hit reimagined for the GBA.', 'The US version of Catch a Ride features the iconic taxis and drivers from the original. Experience the frantic "Arcade" and "Original" city maps, pushing the GBA hardware to deliver 3D-style city navigation and high-speed fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('creatures-eindependent', 'GAMEBOYADVANCE', 'Creatures (E)(Independent)', '2000', 'Simulation', 'Creature Labs', '1', 'Virtual Life', 'Life simulation and artificial life management.', 'Hatch, raise, and teach the Norns to survive on Albia.', 'A portable version of the famous artificial life simulator.', 'Creatures for GBA lets you care for a digital species with their own DNA. Teach your Norns how to eat, speak, and defend themselves from the Grendels in this complex and fascinating biological simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('creatures-eparadox', 'GAMEBOYADVANCE', 'Creatures (E)(Paradox)', '2000', 'Simulation', 'Creature Labs', '1', 'Virtual Life', 'Life simulation and artificial life management.', 'Hatch, raise, and teach the Norns to survive on Albia.', 'A portable version of the famous artificial life simulator.', 'This European release of Creatures offers a unique "digital pet" experience. Manage the ecosystem of your Norns, monitor their health, and guide their evolution through generations in a detailed and interactive world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('croket-3-guranyuoukoku-no-nazo-jrising-sun', 'GAMEBOYADVANCE', 'Croket 3 Guranyuoukoku No Nazo (J)(Rising Sun)', '2002', 'Action RPG', 'Chunsoft', '1', 'Anime Action RPG', '2D fighting game and action-adventure.', 'Battle rivals and collect gold to save your father.', 'An intense brawler based on the popular Croket! manga.', 'Croket 3 Guranyuoukoku No Nazo features fast-paced 1-on-1 combat. Use specialized moves and "Bank" abilities to defeat powerful bosses and uncover the mystery of the Granu Kingdom in this Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('croket!-2-kindan-no-bank-to-banjyu-jevasion', 'GAMEBOYADVANCE', 'Croket! 2 Kindan no Bank To Banjyu (J)(Evasion)', '2001', 'Action RPG', 'Chunsoft', '1', 'Anime Action RPG', '2D fighting game and action-adventure.', 'Compete in the forbidden tournament to win the Bank.', 'High-energy combat and platforming with Croket.', 'Croket! 2 Kindan no Bank To Banjyu expands the fighting mechanics of the original. Navigate through diverse stages, unlock new characters, and master the art of the hammer in this vibrant and action-packed Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('croket!-4---bank-no-mori-no-mamorigami-jcaravan', 'GAMEBOYADVANCE', 'Croket! 4 - Bank no Mori no Mamorigami (J)(Caravan)', '2004', 'Action RPG', 'Chunsoft', '1', 'Anime Action RPG', '2D fighting game and action-adventure.', 'Protect the forest spirits and defeat the invading army.', 'The fourth entry in the hit Japanese action series.', 'Croket! 4 brings refined graphics and a deeper story mode. Battle through waves of enemies and engage in tactical boss fights, utilizing the unique powers of the Forest Guardians to protect the land.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crouching-tiger-hidden-dragon-ecezar', 'GAMEBOYADVANCE', 'Crouching Tiger Hidden Dragon (E)(Cezar)', '2003', 'Action Adventure', 'Genki', '1', 'Martial Arts Action', 'Side-scrolling beat ''em up and action.', 'Recover the Green Destiny sword and defeat Jade Fox.', 'A martial arts epic based on the Oscar-winning film.', 'Crouching Tiger Hidden Dragon features fluid combat and acrobatic movement. Master the light-foot skills to run on walls and engage in cinematic sword duels as Li Mu Bai, Yu Shu Lien, or Jen Yu.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crouching-tiger-hidden-dragon-ueurasia', 'GAMEBOYADVANCE', 'Crouching Tiger Hidden Dragon (U)(Eurasia)', '2003', 'Action Adventure', 'Genki', '1', 'Martial Arts Action', 'Side-scrolling beat ''em up and action.', 'Recover the Green Destiny sword and defeat Jade Fox.', 'A martial arts epic based on the Oscar-winning film.', 'The US version of Crouching Tiger Hidden Dragon delivers intense Wuxia action. Upgrade your skills, master diverse weapons, and experience the beautiful yet dangerous world of ancient China on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cruisn-velocity-uvenom', 'GAMEBOYADVANCE', 'Cruis''n Velocity (U)(Venom)', '2001', 'Racing', 'Midway', '1', 'Arcade Racing', '3D arcade racing with multiple car classes.', 'Win the championship across futuristic city tracks.', 'The high-speed Nintendo racing franchise on GBA.', 'Cruis''n Velocity features 14 different cars and various international locations. Utilize the nitro system to blast past opponents in this technical showcase that attempts to bring 3D racing to the handheld screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crushed-baseball-uvenom', 'GAMEBOYADVANCE', 'Crushed Baseball (U)(Venom)', '2004', 'Sports', 'Crushed Games', '2', 'Arcade Baseball', 'Arcade-style baseball with super moves.', 'Lead your team of quirky characters to the world series.', 'A fun and exaggerated take on professional baseball.', 'Crushed Baseball features "ultra" moves and power-ups that defy the laws of physics. Pitch flaming balls or hit gravity-defying home runs in this accessible and humor-filled sports simulation for the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ct-special-forces-eeurasia', 'GAMEBOYADVANCE', 'CT Special Forces (E)(Eurasia)', '2003', 'Run and Gun', 'Creative Patterns', '2', 'Arcade Shooter', 'Side-scrolling run-and-gun action.', 'Eliminate terrorist threats and complete elite missions.', 'A high-quality action game similar to Metal Slug.', 'CT Special Forces features intense shooting, sniping segments, and parachute levels. Control elite soldiers through various global conflict zones, utilizing a variety of modern weaponry to stop a terrorist organization.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ct-special-forces-uindependent', 'GAMEBOYADVANCE', 'CT Special Forces (U)(Independent)', '2003', 'Run and Gun', 'Creative Patterns', '2', 'Arcade Shooter', 'Side-scrolling run-and-gun action.', 'Eliminate terrorist threats and complete elite missions.', 'A high-quality action game similar to Metal Slug.', 'The US version of CT Special Forces offers polished 2D graphics and varied gameplay. Switch between different characters and gadgets to navigate through jungles and urban environments in this handheld action hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ct-special-forces-2---back-in-the-trenches-uchameleon', 'GAMEBOYADVANCE', 'CT Special Forces 2 - Back in The Trenches (U)(Chameleon)', '2004', 'Run and Gun', 'Creative Patterns', '2', 'Arcade Shooter', 'Side-scrolling run-and-gun action.', 'Stop the new global threat across diverse combat zones.', 'The explosive sequel with improved combat mechanics.', 'CT Special Forces 2: Back in The Trenches increases the intensity with more weapons and vehicles. Experience refined level design and challenging boss fights in one of the best tactical shooters on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ct-special-forces-2---back-to-hell-erising-sun', 'GAMEBOYADVANCE', 'CT Special Forces 2 - Back to Hell (E)(Rising Sun)', '2004', 'Run and Gun', 'Creative Patterns', '2', 'Arcade Shooter', 'Side-scrolling run-and-gun action.', 'Stop the new global threat across diverse combat zones.', 'The explosive sequel with improved combat mechanics.', 'CT Special Forces 2: Back to Hell (European version) features a grittier tone and more complex mission objectives. Master the stealth and action segments to take down the enemy leadership.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ct-special-forces-3---bioterror-erising-sun', 'GAMEBOYADVANCE', 'CT Special Forces 3 - Bioterror (E)(Rising Sun)', '2005', 'Run and Gun', 'Creative Patterns', '2', 'Arcade Shooter', 'Side-scrolling run-and-gun action.', 'Thwart a global bioterrorism plot and save millions.', 'The final entry in the acclaimed CT Special Forces trilogy.', 'CT Special Forces 3: Bioterror offers the most refined gameplay in the series. Featuring impressive animations and large-scale levels, it’s a definitive run-and-gun experience for fans of military action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cubix---robots-for-everyone---clash-n-bash-uvenom', 'GAMEBOYADVANCE', 'Cubix - Robots for Everyone - Clash ''n Bash (U)(Venom)', '2003', 'Action', 'Arachnid Games', '1', 'Arena Combat', '2D fighting game and arena combat.', 'Use your robot''s abilities to defeat the Eon robots.', 'A robot-brawling game based on the Cubix animated series.', 'Cubix - Robots for Everyone - Clash ''n Bash features a variety of playable robots with unique stats. Upgrade your machine, master the arena, and save Bubble Town in this colorful and fast-paced fighting game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('curious-george-erising-sun', 'GAMEBOYADVANCE', 'Curious George (E)(Rising Sun)', '2006', 'Platformer', 'WayForward', '1', 'Cartoon Platformer', 'Side-scrolling platformer with puzzle elements.', 'Find the Man in the Yellow Hat and explore the city.', 'A gentle and colorful adventure starring the famous monkey.', 'Curious George for GBA is a family-friendly title featuring George''s acrobatic movements. Swing through trees, solve simple environmental puzzles, and participate in fun mini-games based on the movie and books.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('curious-george-utrashman', 'GAMEBOYADVANCE', 'Curious George (U)(Trashman)', '2006', 'Platformer', 'WayForward', '1', 'Cartoon Platformer', 'Side-scrolling platformer with puzzle elements.', 'Find the Man in the Yellow Hat and explore the city.', 'A gentle and colorful adventure starring the famous monkey.', 'The US version of Curious George offers vibrant levels and accessible gameplay. Collect diverse items and navigate through the zoo and city in a safe and engaging adventure perfect for younger players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('custom-robo-gx-jeurasia', 'GAMEBOYADVANCE', 'Custom Robo GX (J)(Eurasia)', '2002', 'Action RPG', 'Noise', '4', 'Arena Combat', 'Isometric arena-based robot combat.', 'Customize your robo and win the GX championship.', 'A deep and strategic Japanese robot-battling RPG.', 'Custom Robo GX features hundreds of parts to collect and equip. Build your custom robot and engage in intense 2D arena battles, utilizing a wide array of weapons and tactical maneuvers in this Japanese gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('custom-robo-gx-japan-t-en-by-hmsong-v03', 'GAMEBOYADVANCE', 'Custom Robo GX (Japan) [T-En by hmsong v0.3]', '2002', 'Action RPG', 'Noise', '4', 'Arena Combat', 'Isometric arena-based robot combat.', 'Customize your robo and win the GX championship.', 'A fan-translated version of the deep robot-battling RPG.', 'Custom Robo GX (English Patch) allows Western fans to finally enjoy this strategic title. Follow the story, understand the complex part stats, and master the "Illegal" robot parts in this high-quality translation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyberdrive-zoids-jrising-sun', 'GAMEBOYADVANCE', 'Cyberdrive Zoids (J)(Rising Sun)', '2004', 'Action', 'Tomy', '1', 'Mecha Combat', 'Isometric mecha-combat and strategy.', 'Pilot your Zoid and defeat the rival faction.', 'A tactical action game based on the Zoids franchise.', 'Cyberdrive Zoids features deep customization and real-time combat. Pilot iconic mechanical beasts, upgrade their weaponry, and navigate through a futuristic world in this detailed Japanese action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daimaajan-jindependent', 'GAMEBOYADVANCE', 'Daimaajan (J)(Independent)', '2000', 'Mahjong', 'ASCII', '1', 'Traditional Board Game', 'Digital Mahjong board game.', 'Outsmart your opponents and become the Mahjong master.', 'A classic and polished Japanese Mahjong simulator.', 'Daimaajan offers a variety of Mahjong modes for the GBA. With adjustable AI difficulty and clean graphics, it provides a high-quality portable experience for fans of the traditional strategic board game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daisenryaku-jcezar', 'GAMEBOYADVANCE', 'Daisenryaku (J)(Cezar)', '2001', 'Strategy', 'SystemSoft Alpha', '1', 'Turn-Based Strategy', 'Turn-based tactical military strategy.', 'Command your army and capture the enemy''s headquarters.', 'A deep and realistic military strategy game for GBA.', 'Daisenryaku features grid-based combat with a focus on modern military units. Manage resources, deploy tanks and aircraft, and utilize the terrain to outthink your opponents in this challenging Japanese simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daisuki-teddy-jwnkmx', 'GAMEBOYADVANCE', 'Daisuki Teddy (J)(WnkMX)', '2002', 'Adventure', 'MTO', '1', 'Children Adventure', 'Virtual pet and social simulation.', 'Take care of your teddy bear and participate in town life.', 'A heartwarming simulation featuring an adorable teddy bear.', 'Daisuki Teddy (I Love Teddy) lets you customize and bond with a magical teddy. Participate in daily activities, play mini-games, and dress up your bear in this cozy and cute Japanese-exclusive game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dan-doh!!-jcaravan', 'GAMEBOYADVANCE', 'Dan Doh!! (J)(Caravan)', '2003', 'Sports', 'Electronic Arts', '1', 'Golf Simulation', 'Sports simulation (Golf) with RPG elements.', 'Win the tournament and climb the professional golf ranks.', 'A golf adventure based on the Dan Doh!! anime.', 'Dan Doh!! features intuitive golfing mechanics and a story-driven career mode. Master the winds and terrain of various courses as you follow Dan''s journey to become a professional golfer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dan-doh!!-xi-jeurasia', 'GAMEBOYADVANCE', 'Dan Doh!! Xi (J)(Eurasia)', '2004', 'Sports', 'Electronic Arts', '1', 'Golf Simulation', 'Sports simulation (Golf) with RPG elements.', 'Win the international tournament and master the fairways.', 'The expanded sequel to the hit Japanese golf game.', 'Dan Doh!! Xi offers more courses, refined controls, and updated character stats. Engage in high-stakes matches and use special shots to dominate the competition in this polished sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dancing-sword-jmegaroms', 'GAMEBOYADVANCE', 'Dancing Sword (J)(Megaroms)', '2002', 'Action RPG', 'Marvelous', '1', 'Isometric Action RPG', 'Side-scrolling rhythm-action brawler.', 'Defeat enemies using musical timing and sword strikes.', 'A unique blend of fighting and rhythm-based gameplay.', 'Dancing Sword for GBA features a creative combat system where your attacks must match the background beat. Choose your hero and battle through mystical Japanese landscapes in this stylish and experimental action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('danny-phantom---dschungelstadt-glightforce', 'GAMEBOYADVANCE', 'Danny Phantom - Dschungelstadt (G)(Lightforce)', '2007', 'Action Platformer', 'Altron', '1', 'Cartoon Platformer', 'Side-scrolling action and flight shooter.', 'Save the city from the spectral Urban Jungle plants.', 'German version of the spectral superhero adventure.', 'Danny Phantom - Dschungelstadt lets you use ghost powers to fight Undergrowth. Fly through the air in shooter segments or fight on foot to protect Amity Park in this localized Nickelodeon action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('danny-phantom---the-ultimate-enemy-erising-sun', 'GAMEBOYADVANCE', 'Danny Phantom - The Ultimate Enemy (E)(Rising Sun)', '2005', 'Action Platformer', 'Altron', '1', 'Cartoon Platformer', '2D action platformer with ghost powers.', 'Defeat your evil future self, Dan Phantom.', 'Stop the ultimate ghost threat in this heroic adventure.', 'Danny Phantom - The Ultimate Enemy is a challenging action game where you master powers like the Ghost Wail. Travel through time and battle spectral bosses to prevent a dark future in this high-stakes platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('danny-phantom---the-ultimate-enemy-esir-vg', 'GAMEBOYADVANCE', 'Danny Phantom - The Ultimate Enemy (E)(Sir VG)', '2005', 'Action Platformer', 'Altron', '1', 'Cartoon Platformer', '2D action platformer with ghost powers.', 'Defeat your evil future self, Dan Phantom.', 'Stop the ultimate ghost threat in this heroic adventure.', 'This European release of The Ultimate Enemy features intense combat and puzzle-solving. Use Danny''s invisibility and intangibility to navigate dangerous ghost-filled levels and save the future.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('danny-phantom---the-ultimate-enemy-utrashman', 'GAMEBOYADVANCE', 'Danny Phantom - The Ultimate Enemy (U)(Trashman)', '2005', 'Action Platformer', 'Altron', '1', 'Cartoon Platformer', '2D action platformer with ghost powers.', 'Defeat your evil future self, Dan Phantom.', 'Stop the ultimate ghost threat in this heroic adventure.', 'The US version of Danny Phantom: The Ultimate Enemy offers fluid animations and faithful storytelling. Master Danny''s combat upgrades to take down Skulker and the dark version of himself in this fan-favorite title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('danny-phantom---urban-jungle-urising-sun', 'GAMEBOYADVANCE', 'Danny Phantom - Urban Jungle (U)(Rising Sun)', '2006', 'Action Platformer', 'Altron', '1', 'Cartoon Platformer', 'Side-scrolling action and flight shooter.', 'Stop the evil plant ghost and save Amity Park.', 'An action-packed adventure featuring Danny''s ghost powers.', 'Danny Phantom - Urban Jungle features high-flying shooter levels and classic platforming. Use specialized ice powers to freeze enemies and explore the spectral depths of the Ghost Zone to save your city.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daredevil-epatience', 'GAMEBOYADVANCE', 'Daredevil (E)(Patience)', '2003', 'Action', 'Sarv', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up and action.', 'Take down the Kingpin and clean up Hell''s Kitchen.', 'Play as the Man Without Fear in this gritty action game.', 'Daredevil for GBA brings the Marvel hero to life. Use your radar sense to detect hidden enemies and master baton-based combat to dismantle the criminal underworld across the rooftops of New York.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daredevil-gtrsi', 'GAMEBOYADVANCE', 'Daredevil (G)(TRSI)', '2003', 'Action', 'Sarv', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up and action.', 'Take down the Kingpin and clean up Hell''s Kitchen.', 'German version of the Marvel superhero brawler.', 'This localized version of Daredevil features the same intense martial arts action. Fight through warehouses and city streets to face off against iconic villains like Bullseye and the Kingpin.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daredevil-umode7', 'GAMEBOYADVANCE', 'Daredevil (U)(Mode7)', '2003', 'Action', 'Sarv', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up and action.', 'Take down the Kingpin and clean up Hell''s Kitchen.', 'Play as the Man Without Fear in this gritty action game.', 'The US version of Daredevil offers atmospheric 2D graphics and challenging boss fights. Utilize your heightened senses to find secret items and defeat the mob in this faithful comic-book adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('darius-r-jeurasia', 'GAMEBOYADVANCE', 'Darius R (J)(Eurasia)', '2000', 'Shooter', 'Taito', '1', 'Horizontal Shooter', 'Horizontal-scrolling shoot ''em up (Shmup).', 'Destroy the Belsar fleet and the giant robotic bosses.', 'A portable entry in the legendary Darius shooter series.', 'Darius R features the iconic fish-themed bosses and branching path system the series is known for. Navigate through intense bullet-hell segments and upgrade your ship''s lasers and shields in this arcade-quality port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-amy', 'GAMEBOYADVANCE', 'Dark Amy', '2002', 'Action', 'Sega', '1', 'Character Mod', '2D side-scrolling action and platforming.', 'Navigate dark levels as a corrupted version of Amy Rose.', 'A fan-made character hack featuring Dark Amy.', 'Dark Amy is a creative modification for Sonic fans. Experience the classic platforming speed with a dark, edgy aesthetic for Amy Rose, featuring modified palettes and adjusted character attributes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-arena-ueurasia', 'GAMEBOYADVANCE', 'Dark Arena (U)(Eurasia)', '2001', 'Shooter', 'Criterion Games', '4', 'Arena Shooter', 'First-person shooter (FPS) and exploration.', 'Escape the secret laboratory and defeat the mutants.', 'One of the few original first-person shooters on GBA.', 'Dark Arena delivers a fast-paced FPS experience on handheld. Navigate through dark corridors, manage your ammo, and blast through hordes of genetically engineered monsters using a variety of futuristic weapons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-hyper-sonic-spanish', 'GAMEBOYADVANCE', 'Dark Hyper Sonic [Spanish]', '2003', 'Action', 'Sega', '1', 'Character Mod', 'High-speed 2D platforming and action.', 'Race through levels as the ultimate powered-up Sonic.', 'A Spanish-localized fan hack featuring Dark Hyper Sonic.', 'Dark Hyper Sonic [Spanish] provides a unique take on the Blue Blur. Play through familiar levels with incredible speed and the visual flair of the Hyper form, now translated for Spanish-speaking fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-shadow-in-sonic-battle', 'GAMEBOYADVANCE', 'Dark Shadow in Sonic Battle', '2003', 'Action', 'Sega', '1', 'Character Mod', '2D arena-based fighting and combat.', 'Defeat all rivals in the tournament as Dark Shadow.', 'A character hack for the tactical fighter Sonic Battle.', 'Dark Shadow in Sonic Battle replaces the standard Shadow with his dark, corrupted form. Master the deep combo system and unique special moves in this stylized 2D arena brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-sonic-in-sonic-battle!', 'GAMEBOYADVANCE', 'Dark Sonic in Sonic Battle!', '2003', 'Action', 'Sega', '1', 'Character Mod', '2D arena-based fighting and combat.', 'Dominate the battle arena as the powerful Dark Sonic.', 'A character hack for the tactical fighter Sonic Battle.', 'Dark Sonic in Sonic Battle! brings the rare transformation to the combat arena. Experience new visual effects and powerful movesets as you battle through the story mode with this aggressive version of Sonic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dave-mirra-freestyle-bmx-2-erocket', 'GAMEBOYADVANCE', 'Dave Mirra Freestyle BMX 2 (E)(Rocket)', '2001', 'Sports', 'Full Fat', '2', 'Arcade BMX', 'Extreme sports BMX simulation and stunts.', 'Master the half-pipe and win the pro BMX circuit.', 'High-flying bike stunts with the legend Dave Mirra.', 'Dave Mirra Freestyle BMX 2 features deep trick mechanics and open levels. Perform grinds, flips, and spins to earn points and impress sponsors in this realistic and challenging portable sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dave-mirra-freestyle-bmx-2-uvenom', 'GAMEBOYADVANCE', 'Dave Mirra Freestyle BMX 2 (U)(Venom)', '2001', 'Sports', 'Full Fat', '2', 'Arcade BMX', 'Extreme sports BMX simulation and stunts.', 'Master the half-pipe and win the pro BMX circuit.', 'High-flying bike stunts with the legend Dave Mirra.', 'The US version of Dave Mirra 2 offers smooth controls and a variety of bikes to unlock. Navigate through urban and dirt courses while building your reputation as a world-class BMX rider.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dave-mirra-freestyle-bmx-3-umenace', 'GAMEBOYADVANCE', 'Dave Mirra Freestyle BMX 3 (U)(Menace)', '2002', 'Sports', 'Full Fat', '2', 'Arcade BMX', 'Extreme sports BMX simulation and stunts.', 'Become the top-ranked pro rider by landing epic combos.', 'The third installment in the acclaimed BMX series.', 'Dave Mirra Freestyle BMX 3 improves on the trick system and level variety. Explore massive environments and participate in specialized challenges to prove your skills on the bike.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('david-beckham-soccer-evenom', 'GAMEBOYADVANCE', 'David Beckham Soccer (E)(Venom)', '2002', 'Sports', 'Rage Software', '4', 'Arcade Soccer', 'Soccer simulation and management.', 'Lead your team to victory in international tournaments.', 'A realistic soccer game endorsed by the superstar.', 'David Beckham Soccer for GBA features multiple game modes, including a "Beckham" mode where you relive key career moments. Master the free-kick mechanics and guide your squad to the world championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('david-beckham-soccer-uindependent', 'GAMEBOYADVANCE', 'David Beckham Soccer (U)(Independent)', '2002', 'Sports', 'Rage Software', '4', 'Arcade Soccer', 'Soccer simulation and management.', 'Lead your team to victory in international tournaments.', 'A realistic soccer game endorsed by the superstar.', 'The US version of David Beckham Soccer offers fluid player animations and strategic gameplay. Compete in quick matches or full seasons with a focus on precision passing and set-piece mastery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('davis-cup-emenace', 'GAMEBOYADVANCE', 'Davis Cup (E)(Menace)', '2002', 'Sports', 'Infogrames', '4', 'Tennis Simulation', 'Sports simulation (Tennis) and tournament play.', 'Win the world-renowned Davis Cup for your nation.', 'A realistic and strategic tennis sim for GBA.', 'Davis Cup features a deep tournament mode and various court types. Master the timing of your serves and volleys to defeat international rivals in this polished handheld sports game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('davis-cup-uevasion', 'GAMEBOYADVANCE', 'Davis Cup (U)(Evasion)', '2002', 'Sports', 'Infogrames', '4', 'Tennis Simulation', 'Sports simulation (Tennis) and tournament play.', 'Win the world-renowned Davis Cup for your nation.', 'A realistic and strategic tennis sim for GBA.', 'The US version of Davis Cup offers intuitive controls and multiple difficulty settings. Experience the tension of professional tennis as you represent your country on the global stage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dead-to-rights-erising-sun', 'GAMEBOYADVANCE', 'Dead to Rights (E)(Rising Sun)', '2002', 'Action', 'Torus Games', '1', 'Third-Person Action', 'Third-person isometric action and shooter.', 'Clear your name and hunt down the criminals who framed you.', 'Gritty noir-style action based on the console hit.', 'Dead to Rights for GBA features intense gunplay and the "bullet time" mechanic. Play as Jack Slate, using your canine companion Shadow to assist in combat as you fight through the corruption of Grant City.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dead-to-rights-urising-sun', 'GAMEBOYADVANCE', 'Dead To Rights (U)(Rising Sun)', '2002', 'Action', 'Torus Games', '1', 'Third-Person Action', 'Third-person isometric action and shooter.', 'Clear your name and hunt down the criminals who framed you.', 'Gritty noir-style action based on the console hit.', 'The US version of Dead to Rights offers a cinematic story and varied mission types. Engage in brawls, shootouts, and mini-games in this high-octane portable action thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deadly-skies-epatience', 'GAMEBOYADVANCE', 'Deadly Skies (E)(Patience)', '2003', 'Shooter', 'Rebellion', '1', 'Flight Combat', 'Combat flight simulation and aerial dogfighting.', 'Pilot your jet through dangerous missions and dogfights.', 'High-speed aerial combat with a variety of modern jets.', 'Deadly Skies (known as AirForce Delta) delivers arcade-style flight action. Complete diverse objectives from base defense to escort missions while mastering the controls of authentic military aircraft.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deal-or-no-deal-usir-vg', 'GAMEBOYADVANCE', 'Deal or No Deal (U)(Sir VG)', '2006', 'Game Show', 'Mobius Entertainment', '1', 'TV Game Show', 'Trivia and probability-based game show.', 'Choose the right suitcase and beat the Banker for $1,000,000.', 'The official handheld version of the hit TV show.', 'Deal or No Deal for GBA captures the suspense of the high-stakes game. Manage your luck and nerves of steel as you eliminate cases and decide whether to take the Banker''s offer or risk it all for the grand prize.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('defender-epatience', 'GAMEBOYADVANCE', 'Defender (E)(Patience)', '2002', 'Shooter', 'Midway', '2', 'Classic Arcade Shooter', 'Side-scrolling shooter and tower defense.', 'Protect human survivors and blast alien invaders.', 'A reimagined version of the arcade classic for GBA.', 'Defender brings the retro legend into the modern era with updated graphics and new weapons. Defend your colonies from abduction and master the fast-paced, 360-degree flight mechanics of your starship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('defender-uvenom', 'GAMEBOYADVANCE', 'Defender (U)(Venom)', '2002', 'Shooter', 'Midway', '2', 'Classic Arcade Shooter', 'Side-scrolling shooter and tower defense.', 'Protect human survivors and blast alien invaders.', 'A reimagined version of the arcade classic for GBA.', 'The US version of Defender features intense space combat and multiple ship upgrades. Blast through waves of aliens and ensure the survival of humanity in this high-energy arcade shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('defender-of-the-crown-ebatman', 'GAMEBOYADVANCE', 'Defender of the Crown (E)(BatMan)', '2002', 'Strategy', 'Cinemaware', '1', 'Medieval Strategy', 'Medieval strategy and resource management.', 'Conquer the kingdoms and reclaim the throne of England.', 'A deep and strategic port of the classic Amiga title.', 'Defender of the Crown features a mix of strategy, jousting, and castle sieges. Manage your armies, participate in tournaments, and use tactical planning to unite the land in this visually impressive GBA remake.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('defender-of-the-crown-uvenom', 'GAMEBOYADVANCE', 'Defender of the Crown (U)(Venom)', '2002', 'Strategy', 'Cinemaware', '1', 'Medieval Strategy', 'Medieval strategy and resource management.', 'Conquer the kingdoms and reclaim the throne of England.', 'A deep and strategic port of the classic Amiga title.', 'The US version of Defender of the Crown offers a rich historical experience. Balance diplomacy and warfare as you compete with rival lords for control of the kingdom in this definitive strategic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('demikids-dark-version-urising-sun', 'GAMEBOYADVANCE', 'Demikids Dark Version (U)(Rising Sun)', '2003', 'RPG', 'ATLUS', '1', 'Turn-Based RPG', 'Monster-collecting RPG and turn-based combat.', 'Travel to the demon world of Dem to save your friends.', 'A dark and deep Shin Megami Tensei spin-off for GBA.', 'DemiKids Dark Version follows Akira on a quest through a world of shadows. Recruit, fuse, and train over 350 demons to fight by your side in this strategic RPG featuring the classic SMT negotiation and fusion mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('demikids-light-version-urising-sun', 'GAMEBOYADVANCE', 'Demikids Light Version (U)(Rising Sun)', '2003', 'RPG', 'ATLUS', '1', 'Turn-Based RPG', 'Monster-collecting RPG and turn-based combat.', 'Explore the world of Valhalla and prevent a demonic war.', 'The lighter, story-parallel companion to the Dark Version.', 'DemiKids Light Version stars Jin in a quest through the celestial realm. With exclusive demons not found in the Dark version, this title offers a deep monster-battling experience with strategic turn-based combat and complex evolution paths.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('demon-driver---time-to-burn-rubber!-utrashman', 'GAMEBOYADVANCE', 'Demon Driver - Time to Burn Rubber! (U)(TrashMan)', '2004', 'Racing', 'SouthPeak Games', '1', 'Arcade Racing', 'Top-down arcade racing and combat.', 'Win the underground street racing circuit.', 'Fast-paced, chaotic driving with a focus on speed and drifting.', 'Demon Driver - Time to Burn Rubber! delivers intense top-down racing action. Master the tight handling of your car to navigate urban tracks, outrun rivals, and avoid obstacles in this high-energy arcade racer for the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('demon-driver-evenom', 'GAMEBOYADVANCE', 'Demon Driver (E)(Venom)', '2004', 'Racing', 'SouthPeak Games', '1', 'Arcade Racing', 'Top-down arcade racing and combat.', 'Win the underground street racing circuit.', 'Fast-paced, chaotic driving with a focus on speed and drifting.', 'The European version of Demon Driver features responsive controls and colorful 2D tracks. Compete in various tournament modes and unlock faster vehicles to dominate the street racing scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('denki-blocks-jchakky', 'GAMEBOYADVANCE', 'Denki Blocks (J)(Chakky)', '2001', 'Puzzle', 'Masaya', '1', 'Block Puzzle', 'Grid-based puzzle and block sliding.', 'Slide blocks together to form shapes and clear the board.', 'A clever and addictive puzzle game with a unique "sticky" mechanic.', 'Denki Blocks (Japanese version) challenges your spatial reasoning. All blocks of the same color move in unison; your goal is to join them together while navigating around obstacles in hundreds of brain-teasing levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('denki-blocks-utrashman', 'GAMEBOYADVANCE', 'Denki Blocks (U)(Trashman)', '2001', 'Puzzle', 'Masaya', '1', 'Block Puzzle', 'Grid-based puzzle and block sliding.', 'Slide blocks together to form shapes and clear the board.', 'A clever and addictive puzzle game with a unique "sticky" mechanic.', 'The US version of Denki Blocks offers a polished puzzle experience. With various difficulty settings and a clean interface, it''s perfect for casual players looking for a unique logic challenge on their handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('denki-blocks!-equartex', 'GAMEBOYADVANCE', 'Denki Blocks! (E)(Quartex)', '2001', 'Puzzle', 'Masaya', '1', 'Block Puzzle', 'Grid-based puzzle and block sliding.', 'Slide blocks together to form shapes and clear the board.', 'A clever and addictive puzzle game with a unique "sticky" mechanic.', 'Denki Blocks! (European version) includes a robust single-player campaign and competitive puzzle modes. Master the "sticky" block physics to solve increasingly complex layouts and become a Denki master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('densetsu-no-stafi-2-jeurasia', 'GAMEBOYADVANCE', 'Densetsu no Stafi 2 (J)(Eurasia)', '2003', 'Platformer', 'Nintendo', '1', 'Side-Scrolling Platformer', 'Underwater platformer and adventure.', 'Help Stafi save his mother and reclaim the Puffball Kingdom.', 'The charming second entry in the legendary Stafi series.', 'Densetsu no Stafi 2 expands the underwater mechanics with new transformations and abilities. Help the star-shaped prince navigate beautiful ocean worlds and defeat quirky bosses in this polished Japanese platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('densetsu-no-stafi-3-jcaravan', 'GAMEBOYADVANCE', 'Densetsu no Stafi 3 (J)(Caravan)', '2004', 'Platformer', 'Nintendo', '1', 'Side-Scrolling Platformer', 'Underwater platformer and adventure.', 'Team up with Stafi''s sister, Stapi, to defeat evil forces.', 'The final GBA adventure of the Puffball prince and his sister.', 'Densetsu no Stafi 3 introduces Stapi as a playable character. Enjoy cooperative-style mechanics, vibrant 2D graphics, and the series'' most creative level designs in this definitive Japanese handheld exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('densetsu-no-stafy-eng-translation', 'GAMEBOYADVANCE', 'Densetsu no Stafy (Eng. Translation)', '2002', 'Platformer', 'Nintendo', '1', 'Side-Scrolling Platformer', 'Underwater platformer and adventure.', 'Navigate ocean worlds to return to the Puffball Kingdom.', 'The first Stafi adventure, now fully playable in English.', 'Densetsu no Stafy (English Translation) allows Western fans to enjoy this Nintendo gem. Experience the fluid swimming mechanics, charming characters, and secrets of the ocean in this high-quality fan translation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('densetsu-no-stafy-jeurasia', 'GAMEBOYADVANCE', 'Densetsu no Stafy (J)(Eurasia)', '2002', 'Platformer', 'Nintendo', '1', 'Side-Scrolling Platformer', 'Underwater platformer and adventure.', 'Navigate ocean worlds to return to the Puffball Kingdom.', 'The debut of the star-shaped prince on the Game Boy Advance.', 'Densetsu no Stafy is a masterpiece of 2D platforming. Control Stafi through diverse aquatic levels, using spins and glides to overcome enemies and save the undersea world in this Japanese classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('derby-stallion-advance-jpolla', 'GAMEBOYADVANCE', 'Derby Stallion Advance (J)(Polla)', '2002', 'Simulation', 'Game Addict', '1', 'Horse Racing Management', 'Horse racing management and simulation.', 'Breed, train, and race your way to the Triple Crown.', 'A deep and realistic horse racing simulation for GBA.', 'Derby Stallion Advance puts you in the role of a stable owner. Manage every aspect of your horses'' careers, from bloodline selection to race tactics, in this highly detailed and popular Japanese simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('desert-strike-advance-uvenom', 'GAMEBOYADVANCE', 'Desert Strike Advance (U)(Venom)', '2002', 'Shooter', 'Electronic Arts', '1', 'Isometric Shooter', 'Isometric helicopter combat and strategy.', 'Complete tactical missions and destroy enemy installations.', 'An elite military flight action game based on the 16-bit hit.', 'Desert Strike Advance brings the legendary Strike series to your pocket. Pilot an Apache helicopter through open-ended desert missions, managing fuel and ammo while rescuing hostages and dismantling a dictator''s regime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('detective-conan-jindependent', 'GAMEBOYADVANCE', 'Detective Conan (J)(Independent)', '2001', 'Adventure', 'Banpresto', '1', 'Detective Adventure', 'Point-and-click adventure and puzzle solving.', 'Solve complex crimes as the genius detective Conan Edogawa.', 'A mystery-solving adventure based on the hit anime series.', 'Detective Conan for GBA (Meitantei Conan) features multiple cases that require sharp observation and logic. Search for clues, interview suspects, and use Conan’s gadgets to uncover the truth in this Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deutschland-sucht-den-superstar-grising-sun', 'GAMEBOYADVANCE', 'Deutschland sucht den Superstar (G)(Rising Sun)', '2003', 'Music', 'Gamehouse', '1', 'Talent Show Game', 'Music rhythm and talent show simulation.', 'Perform your way to the top of the pop charts.', 'The official game of the German "Pop Idol" singing competition.', 'Deutschland sucht den Superstar features rhythm-based gameplay where you must hit the notes to impress the judges. Customize your avatar and climb the ranks of the reality show in this localized music title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dexters-lab---chess-challenge-uvenom', 'GAMEBOYADVANCE', 'Dexter''s Lab - Chess Challenge (U)(Venom)', '2002', 'Board Game', 'High Voltage Software', '2', 'Chess Game', 'Strategic board game with cartoon characters.', 'Outsmart Mandark and win the intergalactic chess tournament.', 'A unique blend of traditional chess and Dexter''s Lab humor.', 'Dexter''s Lab - Chess Challenge offers a fun way to learn and play chess. Featuring characters from the show and specialized challenges, it’s a perfect strategy game for younger fans of the boy genius.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dexters-laboratory---chess-challenge-eindependent', 'GAMEBOYADVANCE', 'Dexter''s Laboratory - Chess Challenge (E)(Independent)', '2002', 'Board Game', 'High Voltage Software', '2', 'Chess Game', 'Strategic board game with cartoon characters.', 'Outsmart Mandark and win the intergalactic chess tournament.', 'A unique blend of traditional chess and Dexter''s Lab humor.', 'The European version of Chess Challenge features various difficulty levels and multiplayer modes. Master the board and use Dexter’s intelligence to defeat his rivals in this polished strategic title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dexters-laboratory---deesaster-strikes-egba', 'GAMEBOYADVANCE', 'Dexter''s Laboratory - Deesaster Strikes (E)(GBA)', '2001', 'Action Platformer', 'Magic Pockets', '1', 'Cartoon Platformer', 'Isometric action platformer and puzzle.', 'Stop Dee Dee from destroying Dexter''s secret laboratory.', 'A chaotic and fun adventure through the eyes of a boy genius.', 'Dexter''s Laboratory - Deesaster Strikes lets you explore the lab''s most dangerous sectors. Use Dexter’s gadgets to fix the chaos caused by his sister, battling rogue robots and solving environmental puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dexters-laboratory---deesaster-strikes!-uvenom', 'GAMEBOYADVANCE', 'Dexter''s Laboratory - Deesaster Strikes! (U)(Venom)', '2001', 'Action Platformer', 'Magic Pockets', '1', 'Cartoon Platformer', 'Isometric action platformer and puzzle.', 'Stop Dee Dee from destroying Dexter''s secret laboratory.', 'A chaotic and fun adventure through the eyes of a boy genius.', 'The US version of Deesaster Strikes! features vibrant graphics and varied mission objectives. Navigate through the laboratory’s hazards and prove that science can save the day in this action-packed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diadroids-world-jindependent', 'GAMEBOYADVANCE', 'Diadroids World (J)(Independent)', '2001', 'Action', 'Sunsoft', '1', 'Arcade Action', 'Monster-battling RPG and adventure.', 'Collect and train Diadroids to become the world champion.', 'A Japanese creature-battling game with a robotic twist.', 'Diadroids World features unique robotic creatures that you can customize and evolve. Engage in tactical battles and explore a futuristic world in this engaging Japanese-exclusive RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diddy-kong-pilot-2003-prototype', 'GAMEBOYADVANCE', 'Diddy Kong Pilot (2003 Prototype)', '2003', 'Racing', 'Rare', '4', 'Arcade Racing', 'Kart racing and flight simulation.', 'Race through diverse tracks in this unreleased Rare classic.', 'A rare look at the predecessor to Banjo-Pilot.', 'Diddy Kong Pilot (2003 Prototype) offers a unique glimpse into development history. Experience 3D-style flight racing with the Kong family in this fully playable but officially unreleased GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('die-biene-maja-klatschmohnwiese-in-gefahr-grising-sun', 'GAMEBOYADVANCE', 'Die Biene Maja Klatschmohnwiese in Gefahr (G)(Rising Sun)', '2003', 'Platformer', 'Shin''en', '1', 'Children’s Platformer', 'Side-scrolling platformer and adventure.', 'Save the poppy field from the invading hornets.', 'A colorful adventure starring the famous Maya the Bee.', 'Die Biene Maja (Maya the Bee) features gentle platforming and exploration. Navigate through nature, help your insect friends, and protect the hive in this charming German-localized adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('die-monster-ag-gadvance-power', 'GAMEBOYADVANCE', 'Die Monster AG (G)(Advance-Power)', '2001', 'Action Platformer', 'Traveller’s Tales', '1', 'Movie-Based Platformer', 'Side-scrolling platformer and mini-games.', 'Collect screams and navigate the city of Monstropolis.', 'The German-localized edition of the Pixar movie hit.', 'Die Monster AG (Monsters, Inc.) lets you play as Sulley and Mike. Navigate through human-world locations and the scream factory, using each character''s skills to solve puzzles and find Boo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('die-unglaublichen-grising-sun', 'GAMEBOYADVANCE', 'Die Unglaublichen (G)(Rising Sun)', '2004', 'Action Platformer', 'Heavy Iron Studios', '1', 'Movie-Based Platformer', 'Side-scrolling action platformer.', 'Use the family''s super powers to stop Syndrome''s plot.', 'The German-localized version of the Incredible superhero game.', 'Die Unglaublichen (The Incredibles) features high-energy action levels. Control Mr. Incredible, Dash, and Violet, utilizing their unique abilities to fight robots and navigate through the island of Nomanisan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('die-wilden-fussball-kerle---entscheidung-im-teufelstopf-gsupplex', 'GAMEBOYADVANCE', 'Die wilden Fussball Kerle - Entscheidung im Teufelstopf (G)(sUppLeX)', '2003', 'Sports', 'Ascaron', '4', 'Arcade Soccer', 'Soccer simulation and social adventure.', 'Lead your team of "Wild Guys" to soccer victory.', 'Based on the popular German movie and book series.', 'Entscheidung im Teufelstopf features a mix of soccer matches and story-driven missions. Help the Wild Guys prove they are the toughest team on the pitch in this localized sports adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('die-wilden-fussball-kerle---gefahr-im-wilde-kerle-land-gsupplex', 'GAMEBOYADVANCE', 'Die Wilden Fussball Kerle - Gefahr im Wilde Kerle Land (G)(sUppLeX)', '2004', 'Sports', 'Ascaron', '4', 'Arcade Soccer', 'Soccer simulation and social adventure.', 'Protect the Wild Guys'' territory from rival teams.', 'Another exciting chapter in the German Wild Soccer Bunch series.', 'Gefahr im Wilde Kerle Land offers more soccer challenges and adventure gameplay. Navigate through the woods and participate in high-stakes matches to defend your home turf.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digi-charat-digicommunication-jchakky', 'GAMEBOYADVANCE', 'DiGi Charat DigiCommunication (J)(Chakky)', '2001', 'Adventure', 'Broccoli', '1', 'Visual Novel Adventure', 'Visual novel and mini-game collection.', 'Communicate with Digi Charat and play various games.', 'A cute Japanese title based on the DiGi Charat anime.', 'DigiCommunication focuses on interacting with Dejiko and her friends. Complete mini-games and follow lighthearted story segments in this beautifully illustrated Japanese-exclusive social game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digi-communication-2-in-1-datou!-black-gemagema-dan-jcaravan', 'GAMEBOYADVANCE', 'Digi Communication 2 in 1 Datou! Black Gemagema Dan (J)(Caravan)', '2002', 'Adventure', 'Broccoli', '1', 'Visual Novel Adventure', 'Multi-genre adventure and mini-game pack.', 'Defeat the Black Gemagema Gang and save the city.', 'The 2-in-1 sequel featuring expanded gameplay and stories.', 'Digi Communication 2 in 1 offers even more content for fans of the series. Engage in diverse challenges and enjoy the unique humor of the DiGi Charat universe on your handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-adventure', 'GAMEBOYADVANCE', 'Digimon Adventure', '2001', 'RPG', 'Bandai', '1', 'Monster RPG', 'Monster-collecting RPG and adventure.', 'Experience the story of the first Digimon anime season.', 'A fan-made or unofficial adventure in the Digimon world.', 'Digimon Adventure for GBA lets you relive the journey of the eight DigiDestined. Collect your favorite Digimon, evolve them through battle, and explore the Digital World in this nostalgic RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-battle-spirit-esuxxors', 'GAMEBOYADVANCE', 'Digimon Battle Spirit (E)(Suxxors)', '2001', 'Fighting', 'Dimps', '4', 'Arena Fighter', '2D arena-based fighting and platforming.', 'Collect spirit motes and defeat your rivals in the arena.', 'Fast-paced combat featuring the stars of Digimon Tamers.', 'Digimon Battle Spirit features a unique fighting system where you must collect orbs from your opponents. Play as Guilmon, Terriermon, and others, using their "Digivolve" forms to dominate the arena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-battle-spirit-unoitami', 'GAMEBOYADVANCE', 'Digimon Battle Spirit (U)(Noitami)', '2002', 'Action RPG', 'ATLUS', '1', 'Action RPG', '2D arena-based fighting and platforming.', 'Collect spirit motes and defeat your rivals in the arena.', 'The US version of the high-energy Digimon fighter.', 'Battle Spirit for GBA delivers intense 1-on-1 action. Master each character''s special attacks and time your evolutions perfectly to win the tournament in this polished handheld brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-battle-spirit-2-eindependent', 'GAMEBOYADVANCE', 'Digimon Battle Spirit 2 (E)(Independent)', '2002', 'Action RPG', 'ATLUS', '1', 'Action RPG', '2D arena-based fighting and platforming.', 'Master the power of Digivolution and win the championship.', 'The sequel featuring characters from Digimon Frontier.', 'Digimon Battle Spirit 2 introduces the "Ancient Spirit" evolutions. Fight through diverse stages, utilize environmental hazards, and collect the most motes to prove you are the ultimate tamer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-battle-spirit-2-urising-sun', 'GAMEBOYADVANCE', 'Digimon Battle Spirit 2 (U)(Rising Sun)', '2003', 'Action RPG', 'ATLUS', '1', 'Action RPG', '2D arena-based fighting and platforming.', 'Master the power of Digivolution and win the championship.', 'The US version of the second Battle Spirit tournament.', 'Battle Spirit 2 (US) offers refined graphics and new combat mechanics. Choose your favorite Frontier warrior and battle through waves of enemies in this fast-paced and colorful fighting game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-emerald-project', 'GAMEBOYADVANCE', 'Digimon Emerald Project', '2023', 'RPG', 'Fan Hack', '1', 'Monster RPG', 'Monster-collecting RPG and turn-based combat.', 'Become the Digimon Master in the Emerald region.', 'A massive Pokémon Emerald hack replaced with Digimon.', 'Digimon Emerald Project is a total conversion hack of Pokémon Emerald. Featuring over 200 Digimon with custom types, cries, and evolution lines, it offers a fresh RPG experience where you battle and trade your favorite Digital Monsters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-nova-red', 'GAMEBOYADVANCE', 'Digimon Nova Red', '2023', 'RPG', 'Fan Hack', '1', 'Monster RPG', 'Monster-collecting RPG and turn-based combat.', 'Navigate the Kanto region with a team of powerful Digimon.', 'A high-quality FireRed hack featuring Digimon creatures.', 'Digimon Nova Red replaces the entire Pokémon cast with Digimon. This hack features updated graphics, a higher difficulty curve, and a refined "Digivolution" system that mirrors the classic anime and tamagotchi experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-racing-erising-sun', 'GAMEBOYADVANCE', 'Digimon Racing (E)(Rising Sun)', '2004', 'Racing', 'Spike', '4', 'Arcade Racing', 'Kart racing with power-ups and Digivolution.', 'Win the Digimon Grand Prix and save the Digital World.', 'High-speed kart racing featuring your favorite Digimon.', 'Digimon Racing for GBA combines classic kart mechanics with unique Digivolution zones. Use speed boosts and specialized attacks while navigating through colorful tracks inspired by the Digital World''s diverse environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-racing-jeurasia', 'GAMEBOYADVANCE', 'Digimon Racing (J)(Eurasia)', '2004', 'Racing', 'Spike', '4', 'Arcade Racing', 'Kart racing with power-ups and Digivolution.', 'Win the Digimon Grand Prix and save the Digital World.', 'The original Japanese release of the Digimon kart racer.', 'Digimon Racing (Japanese Version) offers fluid racing physics and impressive sprite-scaling graphics. Choose from a roster of popular Digimon and master the drift mechanics to dominate the championship circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-racing-uchameleon', 'GAMEBOYADVANCE', 'Digimon Racing (U)(Chameleon)', '2004', 'Racing', 'Spike', '4', 'Arcade Racing', 'Kart racing with power-ups and Digivolution.', 'Win the Digimon Grand Prix and save the Digital World.', 'High-speed kart racing featuring your favorite Digimon.', 'The US version of Digimon Racing features a robust adventure mode and competitive multiplayer. Unlock secret characters and utilize strategic Digivolutions to gain an edge over your rivals on the track.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dinotopia---the-timestone-pirates-umode7', 'GAMEBOYADVANCE', 'Dinotopia - The Timestone Pirates (U)(Mode7)', '2003', 'Action Adventure', 'NaturalMotion', '1', 'Isometric Action Adventure', 'Side-scrolling platformer and puzzle-adventure.', 'Find the Timestone and stop the pirates from invading Dinotopia.', 'A prehistoric adventure based on the popular book series.', 'Dinotopia: The Timestone Pirates features 2D platforming and light puzzle-solving. Control the hero through vibrant environments filled with friendly dinosaurs and dangerous pirates in this family-friendly GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-pixar-pack-erivalroms', 'GAMEBOYADVANCE', 'Disney Pixar Pack (E)(RivalRoms)', '2005', 'Compilation', 'Disney Interactive', '1', 'Family Minigame Collection', 'Collection of Disney/Pixar movie-based games.', 'Complete various missions in Finding Nemo and The Incredibles.', 'A 2-in-1 pack featuring two blockbuster Pixar titles.', 'Disney Pixar Pack for GBA bundles two full adventures in one cartridge. Experience the underwater journey of Finding Nemo alongside the high-energy superhero action of The Incredibles for a comprehensive Disney experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-pixar-pack-grising-sun', 'GAMEBOYADVANCE', 'Disney Pixar Pack (G)(Rising Sun)', '2005', 'Compilation', 'Disney Interactive', '1', 'Family Minigame Collection', 'Collection of Disney/Pixar movie-based games.', 'Complete various missions in Finding Nemo and The Incredibles.', 'German-localized edition of the 2-in-1 Pixar game pack.', 'This German Pixar Pack offers double the fun. Navigate the ocean and battle Syndrome''s robots in two faithful handheld adaptations of the beloved animated films.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-pixar-pack-iindependent', 'GAMEBOYADVANCE', 'Disney Pixar Pack (I)(Independent)', '2005', 'Compilation', 'Disney Interactive', '1', 'Family Minigame Collection', 'Collection of Disney/Pixar movie-based games.', 'Complete various missions in Finding Nemo and The Incredibles.', 'Italian-localized edition of the 2-in-1 Pixar game pack.', 'The Italian Pixar Pack brings the magic of the movies to your GBA. Featuring polished gameplay from both Nemo and The Incredibles, it''s a perfect collection for fans of animated adventures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-pixar-pack-sindependent', 'GAMEBOYADVANCE', 'Disney Pixar Pack (S)(Independent)', '2005', 'Compilation', 'Disney Interactive', '1', 'Family Minigame Collection', 'Collection of Disney/Pixar movie-based games.', 'Complete various missions in Finding Nemo and The Incredibles.', 'Spanish-localized edition of the 2-in-1 Pixar game pack.', 'Disney Pixar Pack (Spanish Version) delivers two complete games. Enjoy the platforming challenges and story-driven missions of these iconic Pixar hits translated for Spanish-speaking players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-princesas-sindependent', 'GAMEBOYADVANCE', 'Disney Princesas (S)(Independent)', '2003', 'Adventure', 'Art Co. Ltd.', '1', 'Storybook Adventure', 'Side-scrolling adventure and mini-game collection.', 'Help the Princesses restore magic to their kingdoms.', 'The Spanish version of the magical Disney Princess quest.', 'Disney Princesas for GBA features levels starring Snow White, Cinderella, and Belle. Solve puzzles, collect items, and relive classic movie moments in this charming and colorful handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-princess-uevasion', 'GAMEBOYADVANCE', 'Disney Princess (U)(Evasion)', '2003', 'Adventure', 'Art Co. Ltd.', '1', 'Storybook Adventure', 'Side-scrolling adventure and mini-game collection.', 'Help the Princesses restore magic to their kingdoms.', 'A magical adventure featuring six iconic Disney Princesses.', 'Disney Princess for GBA offers a safe and engaging experience for younger fans. Explore fairytale worlds and complete lighthearted missions as you help each princess achieve her "happily ever after."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-princess-royal-adventure-elightforce', 'GAMEBOYADVANCE', 'Disney Princess Royal Adventure (E)(Lightforce)', '2006', 'Adventure', 'TOSE', '1', 'Storybook Adventure', 'Isometric adventure and social RPG.', 'Find the missing jewels and prepare for the Royal Ball.', 'A deep exploration-based adventure starring the Princesses.', 'Disney Princess Royal Adventure takes players to a sprawling kingdom. Interact with beloved characters, solve environmental puzzles, and customize your experience in this surprisingly deep social adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-princess-royal-adventure-urising-sun', 'GAMEBOYADVANCE', 'Disney Princess Royal Adventure (U)(Rising Sun)', '2006', 'Adventure', 'TOSE', '1', 'Storybook Adventure', 'Isometric adventure and social RPG.', 'Find the missing jewels and prepare for the Royal Ball.', 'A deep exploration-based adventure starring the Princesses.', 'The US version of Royal Adventure features a vast castle to explore. Complete quests for Disney''s most famous heroines while uncovering a magical mystery in this polished and vibrant title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-princesse-fpatience', 'GAMEBOYADVANCE', 'Disney Princesse (F)(Patience)', '2003', 'Adventure', 'Art Co. Ltd.', '1', 'Storybook Adventure', 'Side-scrolling adventure and mini-game collection.', 'Help the Princesses restore magic to their kingdoms.', 'The French version of the magical Disney Princess quest.', 'Disney Princesse (French Version) allows players to step into the shoes of their favorite heroines. Navigate beautifully drawn 2D levels and master simple mini-games in this localized adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-principesse-iindependent', 'GAMEBOYADVANCE', 'Disney Principesse (I)(Independent)', '2003', 'Adventure', 'Art Co. Ltd.', '1', 'Storybook Adventure', 'Side-scrolling adventure and mini-game collection.', 'Help the Princesses restore magic to their kingdoms.', 'The Italian version of the magical Disney Princess quest.', 'Disney Principesse (Italian Version) brings the fairytale world to life. Join Ariel, Jasmine, and others on a series of quests to restore peace and beauty to their respective lands.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-sports-american-football-jpatience', 'GAMEBOYADVANCE', 'Disney Sports American Football (J)(Patience)', '2002', 'Sports', 'Konami', '4', 'Arcade Sports', 'Arcade-style sports (American Football).', 'Lead Mickey and friends to victory on the gridiron.', 'A high-energy, exaggerated take on American Football.', 'Disney Sports American Football features special "magical" moves and high-impact tackles. Customize your team with Disney icons and master the arcade-style strategy to win the championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-sports-basketball-esurplus', 'GAMEBOYADVANCE', 'Disney Sports Basketball (E)(Surplus)', '2002', 'Sports', 'Konami', '4', 'Arcade Sports', 'Arcade-style sports (Basketball).', 'Outscore your rivals with high-flying dunks and magic powers.', 'A fast-paced 3-on-3 basketball game starring Disney icons.', 'Disney Sports Basketball brings the hoops action to GBA. Use unique character abilities to perform gravity-defying shots and steals in this colorful and competitive sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-sports-basketball-jmugs', 'GAMEBOYADVANCE', 'Disney Sports Basketball (J)(Mugs)', '2002', 'Sports', 'Konami', '4', 'Arcade Sports', 'Arcade-style sports (Basketball).', 'Outscore your rivals with high-flying dunks and magic powers.', 'The original Japanese release of the Disney hoops hit.', 'Disney Sports Basketball (Japanese Version) offers arcade-perfect gameplay. Balance your team''s stats and utilize power-ups to dominate the court with Mickey, Donald, and Goofy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-sports-basketball-ugbatemp', 'GAMEBOYADVANCE', 'Disney Sports Basketball (U)(GBATemp)', '2002', 'Sports', 'Konami', '4', 'Arcade Sports', 'Arcade-style sports (Basketball).', 'Outscore your rivals with high-flying dunks and magic powers.', 'The US version of the high-energy Disney hoops game.', 'The US release of Disney Sports Basketball features multiple tournament modes and a deep training system. Master the timing of your dunks to become the king of the court in this flashy sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-sports-football-erising-sun', 'GAMEBOYADVANCE', 'Disney Sports Football (E)(Rising Sun)', '2002', 'Sports', 'Konami', '4', 'Arcade Sports', 'Arcade-style sports (Soccer/Football).', 'Win the international tournament with your favorite Disney team.', 'Fast-paced soccer action with a magical twist.', 'Disney Sports Football (known as Soccer in the US) features intense 5-on-5 matches. Use special items and elemental shots to overcome the rival team in this high-octane handheld sports game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-sports-football-ugbatemp', 'GAMEBOYADVANCE', 'Disney Sports Football (U)(GBATemp)', '2002', 'Sports', 'Konami', '4', 'Arcade Sports', 'Arcade-style sports (Soccer/Football).', 'Win the international tournament with your favorite Disney team.', 'The US version of the Disney-themed soccer brawler.', 'Disney Sports Football (Soccer) offers smooth controls and colorful animations. Experience the thrill of the pitch with a touch of Disney magic as you climb the ranks of the professional leagues.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-sports-motocross-esurplus', 'GAMEBOYADVANCE', 'Disney Sports Motocross (E)(Surplus)', '2002', 'Racing', 'Konami', '4', 'Arcade Motocross', 'Extreme sports (Motocross) and racing.', 'Win the motocross championship and perform epic tricks.', 'High-flying dirt bike racing with Mickey and the gang.', 'Disney Sports Motocross features challenging dirt tracks and a variety of stunt moves. Master the physics of your bike to navigate jumps and outrun your Disney rivals in this fast-paced racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-sports-motocross-jtrashman', 'GAMEBOYADVANCE', 'Disney Sports Motocross (J)(Trashman)', '2002', 'Racing', 'Konami', '4', 'Arcade Motocross', 'Extreme sports (Motocross) and racing.', 'Win the motocross championship and perform epic tricks.', 'The Japanese version of the Disney dirt-bike racer.', 'Disney Sports Motocross (Japanese Version) delivers arcade-style racing on your GBA. Upgrade your bike''s performance and use power-ups to secure the gold medal on every circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-sports-motocross-uvenom', 'GAMEBOYADVANCE', 'Disney Sports Motocross (U)(Venom)', '2002', 'Racing', 'Konami', '4', 'Arcade Motocross', 'Extreme sports (Motocross) and racing.', 'Win the motocross championship and perform epic tricks.', 'The US version of the high-speed Disney motocross title.', 'The US release of Disney Sports Motocross offers competitive racing across various outdoor environments. Use your character''s special abilities to take shortcuts and perform the best stunts in the game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-sports-skateboarding-erising-sun', 'GAMEBOYADVANCE', 'Disney Sports Skateboarding (E)(Rising Sun)', '2002', 'Sports', 'Konami', '4', 'Arcade Skateboarding', 'Extreme sports (Skateboarding) and stunts.', 'Master the half-pipe and complete skate challenges.', 'A Tony Hawk-style skating game featuring Disney characters.', 'Disney Sports Skateboarding lets you grind and flip through urban parks. Choose your favorite Disney star and land massive combos to earn high scores and unlock new gear in this stylish sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-sports-skateboarding-jpatience', 'GAMEBOYADVANCE', 'Disney Sports Skateboarding (J)(Patience)', '2002', 'Sports', 'Konami', '4', 'Arcade Skateboarding', 'Extreme sports (Skateboarding) and stunts.', 'Master the half-pipe and complete skate challenges.', 'The Japanese version of the Disney skating game.', 'Disney Sports Skateboarding (Japanese Version) features responsive controls and vibrant levels. Master the trick system to prove that Mickey and Donald have the best moves on four wheels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-sports-skateboarding-ugbatemp', 'GAMEBOYADVANCE', 'Disney Sports Skateboarding (U)(GBATemp)', '2002', 'Sports', 'Konami', '4', 'Arcade Skateboarding', 'Extreme sports (Skateboarding) and stunts.', 'Master the half-pipe and complete skate challenges.', 'The US version of the Disney skating game.', 'The US release of Disney Sports Skateboarding offers a variety of skate parks and hidden secrets. Complete objectives and enter tournaments to become the ultimate Disney skate champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-sports-snowboarding-epatience', 'GAMEBOYADVANCE', 'Disney Sports Snowboarding (E)(Patience)', '2002', 'Sports', 'Konami', '4', 'Arcade Snowboarding', 'Extreme sports (Snowboarding) and racing.', 'Race down the mountain and perform icy stunts.', 'High-speed snowboarding action with a Disney twist.', 'Disney Sports Snowboarding features branching paths and high-altitude jumps. Use magical items to slow down opponents and land difficult tricks to build your speed boost in this winter sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-sports-snowboarding-jtrashman', 'GAMEBOYADVANCE', 'Disney Sports Snowboarding (J)(Trashman)', '2002', 'Sports', 'Konami', '4', 'Arcade Snowboarding', 'Extreme sports (Snowboarding) and racing.', 'Race down the mountain and perform icy stunts.', 'The Japanese version of the Disney winter sports game.', 'Disney Sports Snowboarding (Japanese Version) delivers fast-paced downhill racing. Navigate through snow-capped mountains and master the art of the board with your favorite Disney characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-sports-soccer-jeurasia', 'GAMEBOYADVANCE', 'Disney Sports Soccer (J)(Eurasia)', '2002', 'Sports', 'Konami', '4', 'Arcade Soccer', 'Arcade-style soccer with magic powers.', 'Win the magical soccer tournament with Disney stars.', 'Fast-paced 5-on-5 soccer featuring Mickey and friends.', 'Disney Sports Soccer (Japanese version) delivers high-energy matches where strategy meets magic. Use specialized character items and elemental "magic" shots to outplay your rivals and claim the championship trophy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-sports-soccer-uvenom', 'GAMEBOYADVANCE', 'Disney Sports Soccer (U)(Venom)', '2002', 'Sports', 'Konami', '4', 'Arcade Soccer', 'Arcade-style soccer with magic powers.', 'Win the magical soccer tournament with Disney stars.', 'Fast-paced 5-on-5 soccer featuring Mickey and friends.', 'The US version of Disney Sports Soccer features smooth animations and addictive arcade gameplay. Choose your team captain from iconic Disney characters and master the special moves to dominate the pitch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-aladdin-ecezar', 'GAMEBOYADVANCE', 'Disney''s Aladdin (E)(Cezar)', '2003', 'Platformer', 'Capcom', '1', 'Side-Scrolling Platformer', 'Side-scrolling action platformer.', 'Navigate Agrabah and the Cave of Wonders to save Jasmine.', 'The legendary Capcom platformer, faithfully ported to GBA.', 'Disney''s Aladdin for GBA brings the 16-bit masterpiece to your handheld. Experience the fluid animation and challenging levels of Agrabah as you use apples and swordplay to defeat Jafar''s guards and find the magic lamp.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-aladdin-jeurasia', 'GAMEBOYADVANCE', 'Disney''s Aladdin (J)(Eurasia)', '2003', 'Platformer', 'Capcom', '1', 'Side-Scrolling Platformer', 'Side-scrolling action platformer.', 'Navigate Agrabah and the Cave of Wonders to save Jasmine.', 'The original Japanese release of the classic Aladdin adventure.', 'Experience the magic of Aladdin in its original Japanese GBA format. Relive the "A Whole New World" carpet ride and master the platforming challenges that made this one of the best movie tie-ins of all time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-aladdin-uindependent', 'GAMEBOYADVANCE', 'Disney''s Aladdin (U)(Independent)', '2003', 'Platformer', 'Capcom', '1', 'Side-Scrolling Platformer', 'Side-scrolling action platformer.', 'Navigate Agrabah and the Cave of Wonders to save Jasmine.', 'The US version of the definitive Aladdin platforming experience.', 'Disney''s Aladdin (US) offers pixel-perfect platforming. Navigate through the Sultan''s dungeon and the fiery Cave of Wonders, featuring the vibrant colors and catchy music that fans of the animated film love.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-brother-bear-eindependent', 'GAMEBOYADVANCE', 'Disney''s Brother Bear (E)(Independent)', '2003', 'Adventure', 'Vicarious Visions', '1', 'Story-Based Adventure', '2D side-scrolling platformer.', 'Journey to the mountain where the lights touch the earth.', 'Play as Kenai and Koda in this heartwarming adventure.', 'Disney''s Brother Bear features diverse gameplay where you switch between the bear duo. Use their unique strengths to navigate the wilderness, solve environmental puzzles, and experience the story of the film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-brother-bear-erising-sun', 'GAMEBOYADVANCE', 'Disney''s Brother Bear (E)(Rising Sun)', '2003', 'Adventure', 'Vicarious Visions', '1', 'Story-Based Adventure', '2D side-scrolling platformer.', 'Journey to the mountain where the lights touch the earth.', 'Play as Kenai and Koda in this heartwarming adventure.', 'The European version of Brother Bear offers vibrant forest environments and accessible platforming. Avoid hunters and interact with characters like Rutt and Tuke in this charming handheld adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-brother-bear-ueurasia', 'GAMEBOYADVANCE', 'Disney''s Brother Bear (U)(Eurasia)', '2003', 'Adventure', 'Vicarious Visions', '1', 'Story-Based Adventure', '2D side-scrolling platformer.', 'Journey to the mountain where the lights touch the earth.', 'Play as Kenai and Koda in this heartwarming adventure.', 'The US version of Brother Bear delivers a fun and family-friendly experience. Master the cooperative mechanics of the bear brothers to overcome obstacles and discover the true meaning of brotherhood.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-cinderella---magical-dreams-usupplex', 'GAMEBOYADVANCE', 'Disney''s Cinderella - Magical Dreams (U)(Supplex)', '2001', 'Platformer', 'Magic Pockets', '1', 'Fairy Tale Platformer', 'Side-scrolling adventure and mini-game collection.', 'Help Cinderella prepare for the ball and find her True Love.', 'A magical Disney adventure featuring the iconic glass slipper.', 'Disney''s Cinderella - Magical Dreams (US) allows players to step into the classic fairytale. Complete tasks for the Fairy Godmother and navigate the chateau while avoiding the traps of the wicked stepmother.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-extreme-skate-adventure-esuxxors', 'GAMEBOYADVANCE', 'Disney''s Extreme Skate Adventure (E)(Suxxors)', '2003', 'Sports', 'Vicarious Visions', '4', 'Arcade Skateboarding', 'Extreme sports (Skateboarding) and stunts.', 'Master the skate park and complete varied challenges.', 'A "Tony Hawk" style skater with Disney and Pixar characters.', 'Disney''s Extreme Skate Adventure uses the pro-skater engine. Ride as characters from Toy Story, Tarzan, or The Lion King, performing grinds and flips across creative, movie-themed urban environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-extreme-skate-adventure-uhyperion', 'GAMEBOYADVANCE', 'Disney''s Extreme Skate Adventure (U)(Hyperion)', '2003', 'Sports', 'Vicarious Visions', '4', 'Arcade Skateboarding', 'Extreme sports (Skateboarding) and stunts.', 'Master the skate park and complete varied challenges.', 'A "Tony Hawk" style skater with Disney and Pixar characters.', 'The US version of Extreme Skate Adventure features a great soundtrack and responsive controls. Create your own skater or choose a Disney favorite to conquer the half-pipes and rails in this high-energy sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-girls-pack-eindependent', 'GAMEBOYADVANCE', 'Disney''s Girls Pack (E)(Independent)', '2004', 'Compilation', 'Disney Interactive', '1', 'Girls Minigame Collection', 'Collection of Disney-themed social games.', 'Complete various fashion and adventure mini-games.', 'A 2-in-1 pack featuring Lizzie McGuire and Princess games.', 'Disney''s Girls Pack (Europe) bundles two popular titles for female fans. Experience the social life of Lizzie McGuire and the magical quests of the Disney Princesses in one convenient GBA cartridge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-girls-pack-ftrsi', 'GAMEBOYADVANCE', 'Disney''s Girls Pack (F)(TRSI)', '2004', 'Compilation', 'Disney Interactive', '1', 'Girls Minigame Collection', 'Collection of Disney-themed social games.', 'Complete various fashion and adventure mini-games.', 'The French-localized 2-in-1 social game collection.', 'This French Girls Pack offers a variety of gameplay styles, from fashion design to light adventure, featuring the most beloved female characters from the Disney and Disney Channel universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-girls-pack-grising-sun', 'GAMEBOYADVANCE', 'Disney''s Girls Pack (G)(Rising Sun)', '2004', 'Compilation', 'Disney Interactive', '1', 'Girls Minigame Collection', 'Collection of Disney-themed social games.', 'Complete various fashion and adventure mini-games.', 'The German-localized 2-in-1 social game collection.', 'Disney''s Girls Pack (German) provides hours of entertainment with themed mini-games. Navigate social scenarios and royal adventures in this polished and accessible handheld compilation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-girls-pack-1-sindependent', 'GAMEBOYADVANCE', 'Disney''s Girls Pack 1 (S)(Independent)', '2004', 'Compilation', 'Disney Interactive', '1', 'Girls Minigame Collection', 'Collection of Disney-themed social games.', 'Complete various fashion and adventure mini-games.', 'The Spanish-localized 2-in-1 social game collection.', 'Disney''s Girls Pack 1 (Spanish) brings the magic of Lizzie McGuire and the Princesses to Spanish-speaking fans. Enjoy diverse challenges and story-driven missions tailored for younger audiences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-herbie---fully-loaded-egp', 'GAMEBOYADVANCE', 'Disney''s Herbie - Fully Loaded (E)(GP)', '2005', 'Racing', 'Climax Racing', '1', 'Arcade Racing', 'Arcade racing and vehicular stunts.', 'Win races and perform tricks with the world''s most famous Beetle.', 'Fast-paced racing action based on the Herbie movie.', 'Herbie - Fully Loaded features high-speed competition across diverse tracks. Use Herbie’s special "personality" moves to outmaneuver rivals and claim the championship in this fun and colorful racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-herbie---fully-loaded-urising-sun', 'GAMEBOYADVANCE', 'Disney''s Herbie - Fully Loaded (U)(Rising Sun)', '2005', 'Racing', 'Climax Racing', '1', 'Arcade Racing', 'Arcade racing and vehicular stunts.', 'Win races and perform tricks with the world''s most famous Beetle.', 'Fast-paced racing action based on the Herbie movie.', 'The US version of Herbie - Fully Loaded offers accessible driving mechanics and vibrant graphics. Master the art of the "Love Bug" and prove that a little car can have a big heart on the race track.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-home-on-the-range-erising-sun', 'GAMEBOYADVANCE', 'Disney''s Home on the Range (E)(Rising Sun)', '2004', 'Adventure', 'Broccoli', '1', 'Story-Based Adventure', 'Action platformer and mission-based adventure.', 'Save the farm from the greedy outlaw Alameda Slim.', 'Play as the brave cows in this Wild West Disney adventure.', 'Disney''s Home on the Range features diverse gameplay styles. Use Maggie, Mrs. Calloway, and Grace to navigate through canyons and towns, utilizing their unique skills to thwart the villain''s plans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-home-on-the-range-umode7', 'GAMEBOYADVANCE', 'Disney''s Home on the Range (U)(Mode7)', '2004', 'Adventure', 'Broccoli', '1', 'Story-Based Adventure', 'Action platformer and mission-based adventure.', 'Save the farm from the greedy outlaw Alameda Slim.', 'Play as the brave cows in this Wild West Disney adventure.', 'The US version of Home on the Range offers a comedic and action-packed experience. Participate in diverse mini-games and platforming levels that capture the Western spirit of the animated film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-kim-possible---revenge-of-monkey-umode7', 'GAMEBOYADVANCE', 'Disney''s Kim Possible - Revenge of Monkey (U)(Mode7)', '2002', 'Action Platformer', 'Vicarious Visions', '1', 'Cartoon Action Platformer', 'Side-scrolling action platformer and stealth.', 'Stop Monkey Fist from stealing ancient mystical artifacts.', 'Use Kim''s gadgets and martial arts to save the day.', 'Revenge of Monkey Fist (US) is a high-energy platformer. Master Kim''s "Kimmunicator" gadgets and acrobatic combat moves to defeat ninjas and monkeys across global locations in this fan-favorite title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-kim-possible-erising-sun', 'GAMEBOYADVANCE', 'Disney''s Kim Possible (E)(Rising Sun)', '2002', 'Action Platformer', 'Vicarious Visions', '1', 'Cartoon Action Platformer', 'Side-scrolling action platformer and stealth.', 'Navigate through dangerous missions to stop global villains.', 'The European debut of Kim Possible on the GBA.', 'Disney''s Kim Possible features fluid animations and challenging level design. Help Kim and Ron Stoppable thwart Dr. Drakken''s latest scheme in this polished and faithful adaptation of the Disney Channel hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-kim-possible-jcaravan', 'GAMEBOYADVANCE', 'Disney''s Kim Possible (J)(Caravan)', '2002', 'Action Platformer', 'Vicarious Visions', '1', 'Cartoon Action Platformer', 'Side-scrolling action platformer and stealth.', 'Navigate through dangerous missions to stop global villains.', 'The original Japanese release of the Kim Possible adventure.', 'Experience Kim''s world-saving missions in this Japanese-localized version. Utilize her signature gadgets and master the timing of her martial arts to overcome any obstacle in your path.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-kim-possible-2---drakkens-demise-urising-sun', 'GAMEBOYADVANCE', 'Disney''s Kim Possible 2 - Drakken''s Demise (U)(Rising Sun)', '2004', 'Action Platformer', 'Vicarious Visions', '1', 'Cartoon Action Platformer', 'Side-scrolling action platformer and stealth.', 'Rescue Ron Stoppable and stop Drakken''s latest plot.', 'The action-packed sequel featuring even more gadgets.', 'Drakken''s Demise (US) improves on the original with better combat and more playable segments for Ron. Navigate through stealth-heavy levels and use new tech to dismantle the villain''s base.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-kim-possible-3---team-possible-utrashman', 'GAMEBOYADVANCE', 'Disney''s Kim Possible 3 - Team Possible (U)(Trashman)', '2005', 'Action Platformer', 'Griptonite Games', '2', 'Cooperative Action Platformer', 'Side-scrolling action platformer and stealth.', 'Team up with Ron and Rufus to stop a global threat.', 'The first Kim Possible game to feature cooperative-style play.', 'Team Possible (US) allows you to switch between Kim and Ron. Use Kim''s agility and Ron''s specialized tools (and Rufus!) to solve environmental puzzles and defeat waves of enemies in this definitive GBA entry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-lilo-&-stitch-epatience', 'GAMEBOYADVANCE', 'Disney''s Lilo & Stitch (E)(Patience)', '2002', 'Action Platformer', 'Digital Eclipse', '1', 'Run and Gun Platformer', 'Side-scrolling action and run-and-gun platforming.', 'Capture the rogue experiments and stop Gantu.', 'An intense and colorful adventure with Stitch and Lilo.', 'Disney''s Lilo & Stitch for GBA features high-octane action. Play as Stitch for heavy combat and shooting segments, or as Lilo for stealth and puzzle-solving in this beautiful tropical adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-lilo-&-stitch-jcaravan', 'GAMEBOYADVANCE', 'Disney''s Lilo & Stitch (J)(Caravan)', '2002', 'Action Platformer', 'Digital Eclipse', '1', 'Run and Gun Platformer', 'Side-scrolling action and run-and-gun platforming.', 'Capture the rogue experiments and stop Gantu.', 'The original Japanese release of the Lilo & Stitch adventure.', 'Experience the chaos of Experiment 626 on your GBA. This Japanese version offers the same frantic shooting and platforming action that fans of the "Hawaiian roller coaster ride" love.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-lilo-&-stitch-umode7', 'GAMEBOYADVANCE', 'Disney''s Lilo & Stitch (U)(Mode7)', '2002', 'Action Platformer', 'Digital Eclipse', '1', 'Run and Gun Platformer', 'Side-scrolling action and run-and-gun platforming.', 'Capture the rogue experiments and stop Gantu.', 'The US version of the explosive Lilo & Stitch adventure.', 'Lilo & Stitch (US) is a technical marvel on the GBA, featuring impressive boss fights and varied gameplay. Use Stitch''s diverse arsenal to blast through enemies while enjoying the charming story of Ohana.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-lilo-&-stitch-2---hamsterveil-havoc-uvenom', 'GAMEBOYADVANCE', 'Disney''s Lilo & Stitch 2 - Hamsterveil Havoc (U)(Venom)', '2004', 'Action Platformer', 'Climax Studios', '1', 'Run and Gun Platformer', 'Side-scrolling action and flight shooter segments.', 'Stop Hamsterviel from using the experiments for evil.', 'The fast-paced sequel with more Stitch-fueled chaos.', 'Hamsterveil Havoc (US) expands the gameplay with new flight levels and enhanced combat moves. Track down rogue experiments across Hawaii and space in this polished and challenging handheld sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-lilo-&-stitch-2-erising-sun', 'GAMEBOYADVANCE', 'Disney''s Lilo & Stitch 2 (E)(Rising Sun)', '2004', 'Action Platformer', 'Climax Studios', '1', 'Run and Gun Platformer', 'Side-scrolling action and flight shooter segments.', 'Stop Hamsterviel from using the experiments for evil.', 'The European version of the high-flying Stitch sequel.', 'Lilo & Stitch 2 (Europe) offers a perfect mix of platforming and arcade-style shooting. Master Stitch''s new abilities and protect your family from the intergalactic threat of Dr. Hamsterviel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-lion-king-esuxxors', 'GAMEBOYADVANCE', 'Disney''s Lion King (E)(Suxxors)', '2003', 'Platformer', 'Vicarious Visions', '1', 'Classic Platformer', 'Side-scrolling action platformer.', 'Reclaim your place as King of the Pride Lands.', 'An enhanced port of the legendary 16-bit Lion King game.', 'Disney''s Lion King (Europe) brings Simba''s journey to the GBA. Navigate through the African savanna, master the "pounce" and "roar," and relive the cinematic moments of the film in this beautiful handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-lion-king-ueurasia', 'GAMEBOYADVANCE', 'Disney''s Lion King (U)(Eurasia)', '2003', 'Platformer', 'Vicarious Visions', '1', 'Classic Platformer', 'Side-scrolling action platformer.', 'Reclaim your place as King of the Pride Lands.', 'An enhanced port of the legendary 16-bit Lion King game.', 'The US version of Lion King features vibrant graphics and the original soundtrack. Grow from a cub to an adult Simba, facing off against Scar and his hyena army in this timeless and challenging platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-magical-quest-2-starring-mickey-and-minnie-erising-sun', 'GAMEBOYADVANCE', 'Disney''s Magical Quest 2 Starring Mickey and Minnie (E)(Rising Sun)', '2002', 'Platformer', 'Capcom', '2', 'Side-Scrolling Platformer', 'Action platformer with costume-switching.', 'Rescue the orphans and stop Baron Pete''s scheme.', 'Mickey and Minnie team up in this vibrant Capcom sequel.', 'Disney''s Magical Quest 2 (The Great Circus Mystery) features cooperative-style play. Switch between Safari, Western, and Vacuum costumes to gain unique abilities and navigate through beautifully designed circus and forest levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-magical-quest-2-starring-mickey-and-minnie-uevasion', 'GAMEBOYADVANCE', 'Disney''s Magical Quest 2 Starring Mickey and Minnie (U)(Evasion)', '2002', 'Platformer', 'Capcom', '2', 'Side-Scrolling Platformer', 'Action platformer with costume-switching.', 'Rescue the orphans and stop Baron Pete''s scheme.', 'Mickey and Minnie team up in this vibrant Capcom sequel.', 'The US version of Magical Quest 2 brings high-quality Capcom platforming to the GBA. Master the unique powers of each magical outfit to uncover secrets and defeat Baron Pete’s whimsical but dangerous bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-magical-quest-3-starring-mickey-and-donald-erising-sun', 'GAMEBOYADVANCE', 'Disney''s Magical Quest 3 Starring Mickey and Donald (E)(Rising Sun)', '2003', 'Platformer', 'Capcom', '2', 'Side-Scrolling Platformer', 'Action platformer with costume-switching.', 'Rescue Donald''s nephews from the Storybook world.', 'The third and final entry in the acclaimed Capcom trilogy.', 'Disney''s Magical Quest 3 stars Mickey and Donald. Use the Knight, Woodchopper, and Magician outfits to solve environmental puzzles and battle through a fantasy world in this definitive handheld platforming experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-magical-quest-3-starring-mickey-and-donald-jeurasia', 'GAMEBOYADVANCE', 'Disney''s Magical Quest 3 Starring Mickey and Donald (J)(Eurasia)', '2003', 'Platformer', 'Capcom', '2', 'Side-Scrolling Platformer', 'Action platformer with costume-switching.', 'Rescue Donald''s nephews from the Storybook world.', 'The original Japanese release of the third Magical Quest.', 'Experience Mickey & Donald Magical Adventure 3 in its original format. Featuring the most refined graphics and costume mechanics of the series, it''s a must-play for fans of classic 16-bit action platformers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-magical-quest-3-starring-mickey-and-donald-utrashman', 'GAMEBOYADVANCE', 'Disney''s Magical Quest 3 Starring Mickey and Donald (U)(Trashman)', '2003', 'Platformer', 'Capcom', '2', 'Side-Scrolling Platformer', 'Action platformer with costume-switching.', 'Rescue Donald''s nephews from the Storybook world.', 'The third and final entry in the acclaimed Capcom trilogy.', 'The US version of Magical Quest 3 offers polished 2D gameplay. Experiment with Donald’s unique costume variations and team up to stop Baron Pete once and for all in this colorful and challenging adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-magical-quest-starring-mickey-and-minnie-epatience', 'GAMEBOYADVANCE', 'Disney''s Magical Quest Starring Mickey and Minnie (E)(Patience)', '2002', 'Platformer', 'Capcom', '2', 'Side-Scrolling Platformer', 'Action platformer with costume-switching.', 'Save Pluto from the clutches of the evil Emperor Pete.', 'The GBA port of the classic SNES magical adventure.', 'Disney''s Magical Quest Starring Mickey and Minnie introduces the iconic costume-change mechanic. Scale the beanstalk and explore the peaks using the Fireman, Climber, and Magician suits in this nostalgic hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-magical-quest-starring-mickey-and-minnie-jeurasia', 'GAMEBOYADVANCE', 'Disney''s Magical Quest Starring Mickey and Minnie (J)(Eurasia)', '2002', 'Platformer', 'Capcom', '2', 'Side-Scrolling Platformer', 'Action platformer with costume-switching.', 'Save Pluto from the clutches of the evil Emperor Pete.', 'The original Japanese release of the first Magical Quest.', 'Mickey no Magical Adventure brings high-fidelity Capcom animation to the GBA. Navigate through the Emperor''s castle and rescue your faithful dog in this pixel-perfect port of the legendary platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-magical-quest-starring-mickey-and-minnie-ueurasia', 'GAMEBOYADVANCE', 'Disney''s Magical Quest Starring Mickey and Minnie (U)(Eurasia)', '2002', 'Platformer', 'Capcom', '2', 'Side-Scrolling Platformer', 'Action platformer with costume-switching.', 'Save Pluto from the clutches of the evil Emperor Pete.', 'The US version of the first Magical Quest adventure.', 'This US release features refined controls and vibrant 2D art. Master the different magical abilities of Mickey and Minnie to overcome puzzles and bosses in one of the GBA''s most charming action games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-party-uvenom', 'GAMEBOYADVANCE', 'Disney''s Party (U)(Venom)', '2002', 'Party', 'Gamehouse', '4', 'Party Minigame Collection', 'Digital board game and mini-game collection.', 'Compete against Disney stars to win the ultimate party.', 'A fun crossover party game featuring Mickey and friends.', 'Disney''s Party for GBA offers a variety of board-game style levels and dozens of competitive mini-games. Choose your favorite Disney character and use strategic items to outwit your rivals and claim victory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-piglets-big-game-esuxxors', 'GAMEBOYADVANCE', 'Disney''s Piglet''s Big Game (E)(Suxxors)', '2003', 'Adventure', 'Doki Denki Studio', '1', 'Storybook Adventure', 'Side-scrolling adventure and puzzle-solving.', 'Help Piglet overcome his fears and save his friends.', 'A brave and heartwarming adventure in the Hundred Acre Wood.', 'Disney''s Piglet''s Big Game features exploration and bravery. Enter the dreams of your friends to help them overcome their worries, using simple puzzles and platforming designed for younger players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-piglets-big-game-ueurasia', 'GAMEBOYADVANCE', 'Disney''s Piglet''s Big Game (U)(Eurasia)', '2003', 'Adventure', 'Doki Denki Studio', '1', 'Storybook Adventure', 'Side-scrolling adventure and puzzle-solving.', 'Help Piglet overcome his fears and save his friends.', 'A brave and heartwarming adventure in the Hundred Acre Wood.', 'The US version of Piglet''s Big Game brings the charm of Winnie the Pooh to life. Navigate through beautifully illustrated environments and learn the value of friendship and courage on your handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-prinzessinnen-gsuxxors', 'GAMEBOYADVANCE', 'Disney''s Prinzessinnen (G)(Suxxors)', '2003', 'Adventure', 'Art Co. Ltd.', '1', 'Storybook Adventure', 'Side-scrolling adventure and mini-game collection.', 'Help the Princesses restore magic to their kingdoms.', 'The German-localized edition of the Disney Princess quest.', 'Disney''s Prinzessinnen lets you play as Snow White, Belle, and more. Complete themed missions and collect items to restore the beauty of the fairytale worlds in this localized GBA adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-tarzan---lappel-de-la-jungle-fpatience', 'GAMEBOYADVANCE', 'Disney''s Tarzan - L''appel de la Jungle (F)(Patience)', '2004', 'Action Platformer', 'Digital Eclipse', '1', 'Jungle Action Platformer', 'Side-scrolling action platformer.', 'Protect the jungle and save your friends from Clayton.', 'Experience the legend of Tarzan in this French-localized hit.', 'L''appel de la Jungle (Tarzan: Return to the Jungle) features fluid vine-swinging and ground-pounding action. Navigate through the canopy and battle dangerous predators to become the King of the Jungle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-tarzan---return-to-the-jungle-umode7', 'GAMEBOYADVANCE', 'Disney''s Tarzan - Return to the Jungle (U)(Mode7)', '2004', 'Action Platformer', 'Digital Eclipse', '1', 'Jungle Action Platformer', 'Side-scrolling action platformer.', 'Protect the jungle and save your friends from Clayton.', 'The high-octane sequel to Tarzan''s first GBA outing.', 'Disney''s Tarzan - Return to the Jungle features impressive animations and varied levels. Master Tarzan''s feral abilities to navigate the deep jungle, the swamps, and the human camp in this action-packed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-tarzan---ruckkehr-in-den-dschungel-ggbanow', 'GAMEBOYADVANCE', 'Disney''s Tarzan - Ruckkehr in den Dschungel (G)(GBANow)', '2004', 'Action Platformer', 'Digital Eclipse', '1', 'Jungle Action Platformer', 'Side-scrolling action platformer.', 'Protect the jungle and save your friends from Clayton.', 'The German-localized version of the Tarzan sequel.', 'Tarzan - Ruckkehr in den Dschungel offers the same intense platforming and combat. Utilize the environment and Tarzan''s strength to thwart the poachers'' plans and protect the gorilla family.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-thats-so-raven-2---supernatural-style-utrashman', 'GAMEBOYADVANCE', 'Disney''s That''s So Raven 2 - Supernatural Style (U)(Trashman)', '2007', 'Adventure', 'Handheld Games', '1', 'TV Show Adventure', 'Social adventure and mini-game collection.', 'Help Raven navigate school life and fashion disasters.', 'A stylish adventure based on the hit Disney Channel show.', 'That''s So Raven 2: Supernatural Style features fashion design, puzzle-solving, and psychic premonition levels. Help Raven and her friends manage their daily lives with a touch of supernatural flair.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-the-jungle-book-upsychosis', 'GAMEBOYADVANCE', 'Disney''s The Jungle Book (U)(Psychosis)', '1994', 'Platformer', 'Eurocom', '1', 'Classic Platformer', 'Side-scrolling action platformer.', 'Guide Mowgli through the jungle to the man-village.', 'A faithful adaptation of the classic Disney animated film.', 'Disney''s The Jungle Book features Mowgli''s acrobatic movement. Swing on vines, toss fruit at enemies, and encounter iconic characters like Baloo and Bagheera in this colorful handheld platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-the-jungle-book-2-epatience', 'GAMEBOYADVANCE', 'Disney''s The Jungle Book 2 (E)(Patience)', '2005', 'Platformer', 'Torus Games', '1', 'Side-Scrolling Platformer', 'Side-scrolling action platformer.', 'Help Mowgli and Shanti escape Shere Khan''s wrath.', 'The sequel to the jungle adventure with new challenges.', 'The Jungle Book 2 features expanded levels and improved graphics. Navigate through the jungle and the human village as you outsmart the tiger Shere Khan in this engaging movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-treasure-planet-epatience', 'GAMEBOYADVANCE', 'Disney''s Treasure Planet (E)(Patience)', '2002', 'Action Adventure', 'Bizarre Creations', '1', 'Isometric Action Adventure', 'Isometric action-adventure and flight segments.', 'Find the legendary Treasure Planet and stop the mutiny.', 'A galactic pirate adventure based on the sci-fi Disney film.', 'Disney''s Treasure Planet features a mix of on-foot exploration and solar-surfing racing. Help Jim Hawkins navigate dangerous alien worlds and find the greatest loot in the galaxy in this polished GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-treasure-planet-uvenom', 'GAMEBOYADVANCE', 'Disney''s Treasure Planet (U)(Venom)', '2002', 'Action Adventure', 'Bizarre Creations', '1', 'Isometric Action Adventure', 'Isometric action-adventure and flight segments.', 'Find the legendary Treasure Planet and stop the mutiny.', 'A galactic pirate adventure based on the sci-fi Disney film.', 'The US version of Treasure Planet offers varied gameplay styles and cinematic storytelling. Master the solar board and use Jim''s gadgets to uncover the secrets of Captain Flint''s map.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-young-pack-erising-sun', 'GAMEBOYADVANCE', 'Disney''s Young Pack (E)(Rising Sun)', '2004', 'Compilation', 'Disney Interactive', '1', 'Kids Minigame Collection', 'Collection of Disney-themed games for kids.', 'Complete varied mini-games with Winnie the Pooh and more.', 'A 2-in-1 pack designed for younger Disney fans.', 'Disney''s Young Pack (Europe) bundles accessible titles featuring beloved characters. From the peaceful Hundred Acre Wood to magical princess quests, it''s a perfect compilation for early gamers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-magical-quest-2-jeurasia', 'GAMEBOYADVANCE', 'Disneys Magical Quest 2 (J)(Eurasia)', '2002', 'Platformer', 'Capcom', '2', 'Side-Scrolling Platformer', 'Action platformer with costume-switching.', 'Rescue the orphans and stop Baron Pete''s scheme.', 'The original Japanese release of the second Magical Quest.', 'Mickey no Magical Adventure 2 (Great Circus Mystery) is a Capcom classic. Experience the high-fidelity pixel art and creative costume mechanics that made the "Magical Quest" series a favorite worldwide.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dk---king-of-swing-erisingcaravan', 'GAMEBOYADVANCE', 'DK - King of Swing (E)(RisingCaravan)', '2003', 'Platformer', 'Paon', '1', 'Physics-Based Platformer', 'Action-puzzle platformer with physics mechanics.', 'Swing and climb to the top of the mountain to win the games.', 'A unique "swinging" adventure featuring the Kong family.', 'DK: King of Swing redefines platforming controls using the L and R buttons to grab with DK''s hands. Master the momentum-based movement to navigate complex levels and collect medals in this creative Nintendo title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dk---king-of-swing-uindependent', 'GAMEBOYADVANCE', 'DK - King of Swing (U)(Independent)', '2003', 'Platformer', 'Paon', '1', 'Physics-Based Platformer', 'Action-puzzle platformer with physics mechanics.', 'Swing and climb to the top of the mountain to win the games.', 'A unique "swinging" adventure featuring the Kong family.', 'The US version of King of Swing offers a fresh take on the DK franchise. Navigate through vibrant worlds and engage in competitive "swinging" mini-games that test your timing and reflexes on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dk-jr-smk', 'GAMEBOYADVANCE', 'DK Jr. (SMK)', '1984', 'Platformer', 'Nintendo', '2', 'Classic Arcade Platformer', 'Single-screen platforming and arcade action.', 'Help Junior rescue his father, Donkey Kong, from Mario.', 'The classic arcade sequel to the original Donkey Kong.', 'DK Jr. (e-Reader port) brings the 8-bit classic to your handheld. Navigate through vines and dodge traps to steal the keys from Mario and set your father free in this faithful retro recreation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dog-trainer-etrashman', 'GAMEBOYADVANCE', 'Dog Trainer (E)(Trashman)', '2005', 'Simulation', 'Hidden Path Entertainment', '1', 'Pet Training Simulation', 'Virtual pet simulation and training.', 'Adopt, raise, and train a variety of cute puppies.', 'A portable dog-care simulator for animal lovers.', 'Dog Trainer for GBA allows you to choose your favorite breed and care for its daily needs. Feed, groom, and teach tricks to your digital pet to compete in dog shows and build a lasting bond.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dog-trainer-2-eindependent', 'GAMEBOYADVANCE', 'Dog Trainer 2 (E)(Independent)', '2006', 'Simulation', 'Hidden Path Entertainment', '1', 'Pet Training Simulation', 'Virtual pet simulation and training.', 'Breed and train the ultimate champion show dog.', 'The expanded sequel to the dog-care simulation.', 'Dog Trainer 2 features more breeds, improved training mini-games, and deeper customization. Manage your dog''s career from a pup to a professional in this detailed and relaxing simulation.');